\vspace*{-0.3\baselineskip}
The main text focuses on the spatially homogeneous (additive-noise) case for clarity. In this Supplement we establish the general multiplicative-noise result, and recover the additive-noise statement of the main text as a special case.
The derivation proceeds as follows. Secs I.A--I.B set notation and assumptions. Sec. I.C recalls the reverse-time diffusion. Sec. I.D derives the midpoint half-step decomposition and the resulting short-time representation of the midpoint-whitened increment. Sec. I.E proves the cancellation of the $O(\sqrt{\mathrm dt})$ non-Gaussian terms under midpoint conditioning, and Sec. I.F shows that the remaining deviation from the associated Gaussian proxy contributes only an $o(\mathrm dt)$ term and yields the multiplicative-noise identity. Throughout the SM, uppercase $\bm X_t$ denotes the stochastic process, lowercase $\bm x$ a conditioned value or integration variable.

\vspace*{-0.5\baselineskip}

\vspace*{-0.5\baselineskip}
\noindent\textbf{$\bullet$ Noise convention.} We use a $d$-dimensional Gaussian white noise $\bm{\xi}(t)$ with
\begin{equation}
    \langle\bm{\xi}(t)\bm{\xi}(t')^\intercal\rangle=\mathbf{I}_d\,\delta(t-t').
    \label{seq:noise_def}
\end{equation}
Equivalently, we introduce a $d$-dimensional standard Wiener process $W_t$ satisfying
$\mathbb{E}[\mathrm{d}W_t]=0$ and
$\mathbb{E}[\mathrm{d}W_t\,\mathrm{d}W_t^\intercal]=\mathbf{I}_d\,\mathrm{d}t$.
Formally, one may view $\mathrm{d}W_t$ as the time integral of the white noise,
i.e.\ $\mathrm{d}W_t = \bm{\xi}(t)\,\mathrm{d}t$.

\bigskip
\noindent\textbf{$\bullet$ Dynamics.} We consider the Itô SDE
\begin{equation}
    \mathrm{d}\bm{X}_t=\bm{F}_I(\bm{X}_t,t)\mathrm{d}t+\matbf{B}(\bm{X}_t,t)\mathrm{d}W_t,\quad\bm{X}_t\in\mathbb{R}^d.
    \label{seq:dynamics_def}
\end{equation}
We define the diffusion matrix $\matbf{D}(\bm{x},t)\coloneq\frac{1}{2}\matbf{a}(\bm{x},t)$,
where $\matbf{a}(\bm{x},t)\coloneq\matbf{B}(\bm{x},t)\matbf{B}(\bm{x},t)^\intercal$. Throughout, we fix $\matbf{B}$ to be the symmetric positive-definite square root of $\matbf{a}$ (i.e., $\matbf{B}=\matbf{a}^{1/2}$), which implies $\matbf{B}=\matbf{B}^\intercal$.
(In a physical overdamped Langevin form $\dot{\bm{x}}=\matbf{\mu}(\bm{x},t)\bm{f}(\bm{x},t)+\matbf{B}(\bm{x},t)\bm{\xi}$, one may absorb the mobility $\matbf{\mu}$ into the drift and relabel $\matbf{\mu}\bm{f}\mapsto\bm{F}_I$; our result depends only on the resulting It\^{o} drift $\bm{F}_I$ and diffusion matrix $\matbf{D}$.)

\bigskip
\noindent\textbf{$\bullet$ Current and current velocity.}
Let $p(\bm{x},t)$ denote the one-time density of $\bm{X}_t$. It is well known that $p$ evolves according to the Fokker-Planck equation, which can be written in conservation (continuity) form $\partial_tp=-\nabla\cdot\bm{j}$ with probability current
\begin{equation}
    \bm{j}(\bm{x},t)\coloneq\bm{F}_I(\bm{x},t)p(\bm{x},t)-
    \frac{1}{2}\nabla\cdot(\matbf{a}(\bm{x},t)p(\bm{x},t))=
    \bm{F}_I\,p-\nabla\cdot(\matbf{D}p),
    \label{seq:def_j}
\end{equation}
where $(\nabla\cdot(\matbf{a}p))_i\coloneq\sum_j\partial_{x_j}(\mathsf{a}_{ij}p)$.
This form of the probability current is standard in the Fokker-Planck description~\cite{risken1996fokkerplanck,gardiner2009stochastic}.
Following the standard representation~\cite{nelson1967dynamical, seifert2012stochastic}, we further introduce the current velocity 
\begin{equation}
    \bm{v}(\bm{x},t)\coloneq\frac{\bm{j}(\bm{x},t)}{p(\bm{x},t)}
    =\bm{F}_I-\frac{\nabla\cdot(\matbf{D}p)}{p}.
    \label{seq:def_v}
\end{equation}

\medskip
\noindent\textbf{$\bullet$ Entropy production rate.}
For overdamped diffusion processes, under suitable smoothness and regularity assumptions (to be specified in the next section), 
the instantaneous total entropy production rate $\sigma_t$ can be expressed in terms of the probability current as
\begin{equation}
    \sigma_t
    \;=\;\int \mathrm{d}\bm{x}\;
    \frac{\bm{j}(\bm{x},t)^\intercal \matbf{D}(\bm{x},t)^{-1}\bm{j}(\bm{x},t)}{p(\bm{x},t)}
    \;=\;\big\langle \bm{v}(\bm{X}_t,t)^\intercal \matbf{D}(\bm{X}_t,t)^{-1}\bm{v}(\bm{X}_t,t)\big\rangle,
    \label{seq:ep_rate}
\end{equation}
where we used $\bm{j}=p\bm{v}$. This is a standard result in stochastic thermodynamics~\cite{seifert2012stochastic}.

\bigskip
\noindent\textbf{$\bullet$ Time Midpoint notation.} Fix a small $\mathrm{d}t>0$ and define
\begin{equation}
    \mathrm{d}\bm{x}(t)\coloneq\bm{X}_{t+\mathrm{d}t}-\bm{X}_t,
    \quad
    t_m\coloneq t+\frac{\mathrm{d}t}{2},
    \quad
    \bm{X}_m\coloneq\bm{X}_{t_m}.
    \label{seq:midpoint_notation}
\end{equation}

\noindent\textbf{$\bullet$ Time midpoint whitened increment.} Let $\matbf{B}_m\coloneq\matbf{B}(\bm{X}_m,t_m)$. We define
\begin{equation}
    \bm{\eta}_t\coloneq\frac{1}{\sqrt{\mathrm{d}t}}\matbf{B}_m^{-1}\mathrm{d}\bm{x}(t).
    \label{seq:def_Binv_dx}
\end{equation}

Here, we emphasize that the scaling $\matbf{B}_m^{-1}\mathrm{d}\bm{x}(t)\mapsto\bm{\eta}_t$ is deterministic for fixed $\mathrm{d}t$ and therefore preserves mutual information: $I(\matbf{B}_m^{-1}\mathrm{d}\bm{x}(t);\bm{X}_m)=I(\bm{\eta}_t;\bm{X}_m)$. In contrast, the whitening map $\mathrm{d}\bm{x}\mapsto\matbf{B}_m^{-1}\mathrm{d}\bm{x}$ depends on the random midpoint $\bm{X}_m$ and thus does not preserve $I(\mathrm{d}\bm{x};\bm{X}_m)$ in general. We therefore study $I(\matbf{B}_m^{-1}\mathrm{d}\bm{x};\bm{X}_m)$ as the natural diffusion-metric-normalized quantity, which reduces to $I(\mathrm{d}\bm{x};\bm{X}_m)$ in the additive-noise case (constant $\matbf{B}$).

\vspace*{-0.8\baselineskip}
We list explicit, checkable sufficient conditions on the coefficients and the law of $\bm{X}_t$ under which all objects defined in Section~I.A are well-posed (in particular the current $\bm{j}$, current velocity $\bm{v}=\bm{j}/p$, and the entropy production rate $\sigma_t$), and under which we may invoke standard results in the diffusion literature (time reversal and short-time density expansions)~\cite{anderson1982reverse,haussmann1986time,li2013maximum,watanabe1987analysis,yang2019anew,kloeden1992numerical,maruyama1955continuous,yoshida1992asymptotic,higa2013estimates,bally2015probabilistic}. Our goal is to establish the main identity rigorously within this broad and physically natural class, rather than to optimize the weakest possible hypotheses.

\medskip
\hypertarget{assumption:A1}{}
\noindent\textbf{(A1) Uniform ellipticity.} There exist $0<\lambda\leq\Lambda<\infty$ such that $\lambda I\leq\matbf{D}(\bm{x},t)\leq\Lambda I$ for all $(\bm{x},t)$.






\bigskip
\hypertarget{assumption:A2}{}
\noindent\textbf{(A2) Regularity and smoothness of coefficients.}
For each $t$, $\bm{F}_I(\cdot,t)\in C^\infty(\mathbb{R}^d)$ and
$\matbf{B}(\cdot,t)\in C_b^\infty(\mathbb{R}^d)$ in $\bm{x}$, where $C_b^\infty(\mathbb{R}^d)$ denotes the class of smooth functions
whose spatial derivatives of all orders are globally bounded. Also for each $\bm x$, both $\bm F_I(\bm x,\cdot)$, $\matbf B(\bm x,\cdot)$ and their spatial derivatives are $C^1$ in time on $[t,t+\mathrm dt]$.
We denote by $\partial_{\bm{x}}^a (\cdot)$
and $\partial_{t}^b(\cdot)$ the corresponding spatial and time derivatives of order $a$ and $b$.


\bigskip
\hypertarget{assumption:A3}{}
\noindent\textbf{(A3) Well-posedness and smooth densities.}
The SDE~\eqref{seq:dynamics_def} admits 
a unique strong non-explosive solution. For each $t>0$, the law of $\bm{X}_t$ admits a strictly positive density $p(\cdot,t)$ such that $p(\cdot,t)$ and $\partial_t p(\cdot, t)$ are $C^\infty(\mathbb{R}^d)$ in $\bm x$. Consequently, the Fokker-Planck equation holds in the classical sense and the current defined in~\eqref{seq:def_j} is well-defined.

\bigskip
\hypertarget{assumption:A4}{}
\noindent\textbf{(A4) Polynomial growth bounds (drift, score and their derivatives).} There exist a constant $C>0$ and an integer $r\geq0$ such that, uniformly for $u\in[t,t+\mathrm{d}t]$,
\begin{equation*}
    \|\partial_{\bm{x}}^a \bm{F}_I(\bm{x},u)\|
    +\|\partial_{\bm x}^b \log p(\bm x,u)\|
    \leq
    C(1+\| \bm{x}\|^r),
    \quad
    a,b\in\mathbb N\cup\{0\}
\end{equation*}

\hypertarget{assumption:A5}{}
\noindent\textbf{(A5) Non-explosion and moment control.}
We assume that the process is non-explosive and that sufficiently high moments are finite on the time interval considered. Concretely, we impose either \textbf{(A5-A)} or \textbf{(A5-B)} below.

\medskip
\hypertarget{assumption:A5-A}{}
\noindent\textbullet\ \textbf{(A5-A) Bounded drift and current case.}
The drift $\bm F_I(\bm x,u)$ and current velocity $\bm v(\bm x,u)$ in~\eqref{seq:def_v} are uniformly bounded in $(\bm x,u)\in\mathbb R^d\times[t,t+\mathrm dt]$. Also all moments exist, i.e.
\begin{equation*}
    \sup_{u\in[t,t+\mathrm{d}t]}\mathbb{E}\!\left[\|\bm X_u\|^{m}\right]<\infty,
    \quad\forall m\in\mathbb N.
\end{equation*}

\hypertarget{assumption:A5-B}{}
\noindent\textbullet\ \textbf{(A5-B) Confined system case.}
There exist $\alpha,\theta>0$ such that 
\begin{equation*}
    \sup_{u\in[t,t+\mathrm{d}t]}\mathbb{E}\!
    \left[\exp\!\big(\theta\|\bm X_u\|^{1+\alpha}\big)\right]<\infty,
    \quad u\in[t,t+\mathrm dt]
\end{equation*}





Assumptions~\hyperlink{assumption:A1}{A1}--\hyperlink{assumption:A5}{A5} should be viewed as an explicit statement of the regularity conditions that are usually left implicit when one says that the dynamics is a smooth overdamped Langevin diffusion. Physically,~\hyperlink{assumption:A1}{A1} is the standard non-degeneracy of the noise,~\hyperlink{assumption:A2}{A2}--\hyperlink{assumption:A3}{(A3)} give the usual smooth well-posed diffusion setting with smooth one-time densities,~\hyperlink{assumption:A4}{A4} restricts the drift/score sector to at most polynomial growth, and~\hyperlink{assumption:A5}{A5} supplies the corresponding non-explosion and moment control. The two alternatives in~\hyperlink{assumption:A5}{A5} cover the most common physical situations:~\hyperlink{assumption:A5-A}{A5-A} describes effectively bounded dynamics, including compact spaces such as motion on a ring, while~\hyperlink{assumption:A5-B}{A5-B} is tailored to unbounded domains with standard Lyapunov-type dissipative drift. Under these assumptions, the time-reversal and short-time expansions used below are standard, and the entropy production rate in~\eqref{seq:ep_rate} is finite.
For later reference,~\hyperlink{assumption:A1}{A1}--\hyperlink{assumption:A3}{A3} justify the time-reversal formula and local short-time expansions,~\hyperlink{assumption:A4}{A4} controls the polynomial-growth coefficients appearing in the remainder bounds, and~\hyperlink{assumption:A5}{A5} is used only for moment/tail control and the localization arguments.

These assumptions are not intended to be minimal. They are a convenient sufficient package without repeated technical bookkeeping. For any fixed truncation order, corresponding finite order hypotheses would suffice. Non-smooth or geometric variants (e.g., periodic identifications, reflecting boundaries, or piecewise-defined drifts) can often be treated by standard localization/truncation and smoothing arguments, but we do not pursue such extensions here.

\vspace*{-0.5\baselineskip}
We briefly recall the reverse-time diffusion needed for the midpoint construction. Under assumptions~\hyperlink{assumption:A1}{A1}-–\hyperlink{assumption:A3}{A3}, the time reversal of an It\^{o} diffusion is again a diffusion with the same diffusion matrix and an explicit reversed drift~\cite{anderson1982reverse,haussmann1986time}. Specializing that standard formula at the midpoint yields~\eqref{seq:get_v}, the identity used below.

A key ingredient is the drift of the time-reversed diffusion. Consider an It\^{o} diffusion on a finite horizon $\left[0, T\right]$
\begin{equation*}
    \mathrm{d}\bm{X}_t=\bm{b}(\bm{X}_t,t)\mathrm{d}t+\matbf{B}(\bm{X}_t,t)\mathrm{d}W_t\,,
\end{equation*}
which satisfies the assumptions \hyperlink{assumption:A1}{A1}--\hyperlink{assumption:A3}{A3}.
Under these assumptions, let $p(\bm{x}, t)$ denote the one-time density of $\bm{X}_t$. 
We then define the time-reversed process by $\bar{\bm{X}}_t \coloneq \bm{X}_{T-t}$ for $t \in [0, T]$. 
With this definition, $\bar{\bm{X}}_t$ is again a diffusion process with the same diffusion matrix $\matbf{a}\coloneq\matbf{B}\matbf{B}^\intercal=2\matbf{D}$ and reversed drift $\bar{\bm{b}}$ given in component form by

\begin{equation}
    \bar{b}_i(\bm{x}, t)=
    -b_i(\bm{x},T-t)+
    \frac{1}{p(\bm{x},T-t)}
    \sum_{j=1}^d
    \partial_{x_j}(\mathsf{a}_{ij}\left(\bm{x},T-t)\,p(\bm{x},T-t)\right).
    \label{seq:def_reversed_drift}
\end{equation}
Equivalently, in vector notation,
\begin{equation*}
    \bar{\bm{b}}(\bm{x}, t)=
    -\bm{b}(\bm{x},T-t)+
    \frac{
    \nabla\cdot\left(
    \matbf{a}(\bm{x},T-t)\,p(\bm{x},T-t)
    \right)
    }{p(\bm{x},T-t)},
    \label{seq:def_reversed_drift_vec}
\end{equation*}
where $(\nabla\cdot(\matbf{a}p))_i\coloneq\sum_j\partial_{x_j}(\mathsf{a}_{ij}p)$~\cite{haussmann1986time}.

Specializing this general formula to the local reversal around the midpoint time $t_m$ (i.e. set $T=t_m$ and evaluate at reversed time $t=0$), and writing the reverse-time drift at time $t_m$ as $\bm{F}_{rev}(\bm{x},t_m)\coloneq\bar{\bm{b}}(\bm{x},0)$, we obtain the local identity

\begin{equation}
    \bm{F}_{rev}(\bm{x},t_m)=-
    \bm{F}_I(\bm{x},t_m)+
    \frac{\nabla\cdot(\matbf{a}(\bm{x},t_m)\,p(\bm{x},t_m))}{p(\bm{x},t_m)}.
    \label{seq:def_F_rev}
\end{equation}
Combining Eq.~\eqref{seq:def_j},~\eqref{seq:def_v} with~\eqref{seq:def_F_rev} at time $t_m$ yields the exact algebraic relation,
\begin{equation}
    \frac{\bm{F}_I(\bm{x},t_m)-\bm{F}_{rev}(\bm{x},t_m)}{2}=
    \bm{F}_I(\bm{x},t_m)-
    \frac{\nabla\cdot(\matbf{D}\,p)}{p}(\bm{x},t_m)=
    \frac{\bm{j}}{p}(\bm{x},t_m)=\bm{v}(\bm{x},t_m).
    \label{seq:get_v}
\end{equation}

Equation~\eqref{seq:get_v} is the algebraic reason midpoint conditioning is special since it turns the difference between forward and reverse half-step drifts into the current velocity.

\vspace*{-0.8\baselineskip}
We now focus on the time-midpoint half-step decomposition, which is the key ingredient of the proof. 
We first introduce the notation and rewrite the normalized time-midpoint whitened increment $\bm\eta_t$ defined in Eq.~(S7) from the perspective of time-midpoint conditioning. 
Hereafter, we use the term ``midpoint'' to refer to the time midpoint. 
For convenience, we define
\[
h := \mathrm{d}t/2, \quad \bm\Delta^+ := \bm{X}_{t_m+h} - \bm{X}_{t_m}, \quad \bm\Delta^- := \bm{X}_{t_m} - \bm{X}_{t_m-h}.
\]
Then, by the definition, the total increment decomposes as $\mathrm{d}\bm{x} = \bm\Delta^+ + \bm\Delta^-$.  
Note that the triplet $(\bm{X}_t, \bm{X}_m, \bm{X}_{t+dt})$ can equivalently be represented as $(\bm{X}_{t_m-h}, \bm{X}_{t_m}, \bm{X}_{t_m+h})$. 
This representation leads to the following key property:

\hypertarget{lem:S1}{}
\textbf{Lemma S1 (conditional independence).} By the Markov property, conditional on $\bm{X}_m\coloneq\bm{X}_{t_m}=\bm{x}$, the past endpoint $\bm{X}_{t_m-h}$ and the future endpoint $\bm{X}_{t_m+h}$ are independent. Consequently, any functionals of the $\bm\Delta^+$ and $\bm\Delta^-$ are conditionally independent given $\bm{X}_m$.

\textit{Proof.} For the joint distribution $p(\bm{X}_{t_m-h}=\bm{x}^-,\bm{X}_m=\bm{x},\bm{X}_{t_m+h}=\bm{x}^+)$, we can write
\begin{equation*}
    p(\bm{X}_{t_m-h}=\bm{x}^-,\bm{X}_m=\bm{x},\bm{X}_{t_m+h}=\bm{x}^+)=p(\bm{X}_{t_m-h}=\bm{x}^-,\bm{X}_{t_m+h}=\bm{x}^+|\bm{X}_m=\bm{x})p(\bm{X}_m=\bm{x}).
\end{equation*}

We also have

\begin{align*}
    p(\bm{X}_{t_m-h}=\bm{x}^-,\bm{X}_m=\bm{x},\bm{X}_{t_m+h}=\bm{x}^+)
    &=p(\bm{X}_{t_m+h}=\bm{x}^+|\bm{X}_m=\bm{x})p(\bm{X}_{m}=\bm{x},\bm{X}_{t_m-h}=\bm{x}^-)
    \\
    &=p(\bm{X}_{t_m+h}=\bm{x}^+|\bm{X}_m=\bm{x})p(\bm{X}_{t_m-h}=\bm{x}^-|\bm{X}_m=\bm{x})p(\bm{X}_{m}=\bm{x}),
\end{align*}
where the first equality holds because of the Markov property. Hence we get 
\begin{equation*}
    p(\bm{X}_{t_m-h}=\bm{x}^-,\bm{X}_{t_m+h}=\bm{x}^+|\bm{X}_m=\bm{x})=p(\bm{X}_{t_m+h}=\bm{x_+}|\bm{X}_m=\bm{x})p(\bm{X}_{t_m-h}=\bm{x}^-|\bm{X}_m=\bm{x}),
\end{equation*}
which means $\bm{X}_{t_m+h}\perp\!\!\!\perp\bm{X}_{t_m-h}\,|\bm{X}_m$. $\square$

Throughout this subsection, we condition on $\bm{X}_m \coloneq\bm{X}_{t_m}= \bm{x}$.

\bigskip
\noindent\textbf{$\bullet$ Conditional mean and covariance}

\hyperlink{lem:S1}{Lemma S1} makes the conditional mean and covariance of $\mathrm{d}\bm{x}$ easy to compute because $\bm\Delta^+$ and $\bm\Delta^-$ are conditionally independent given $\bm{X}_m=\bm{x}$.
For the forward half-step, by using standard properties of It\^{o} diffusions, we obtain
\begin{equation}
    \mathbb{E}[\bm\Delta^+|\bm{X}_m=\bm{x}]=
    \bm{F}_I(\bm{x},t_m)\,h+o(h).
    \label{seq:E_Delta^+}
\end{equation}

For the backward half-step, define the reversed process $\bar{\bm{X}}_s\coloneq\bm{X}_{t_m-s}$. Then $\bar{\bm{X}}$ is a diffusion whose drift at $s=0$ equals $\bm{F}_{rev}(\bm{x},t_m)$ (Section C). Hence
\begin{equation*}
    \mathbb{E}\left[
    \bm{X}_{t_m-h}-\bm{X}_{t_m}\,|\,\bm{X}_m=\bm{x}
    \right]=
    \mathbb{E}\left[
    \bar{\bm{X}}_h-\bar{\bm{X}}_0\,|\,\bar{\bm{X}}_0=\bm{x}
    \right]=\bm{F}_{rev}(\bm{x},t_m)\,h+o(h),
\end{equation*}
equivalently 
\begin{equation}
    \mathbb{E}\left[\bm\Delta^-|\bm{X}_m=\bm{x}\right]=-\bm{F}_{rev}(\bm{x},t_m)\,h+o(h).
    \label{seq:E_Delta^-}
\end{equation} 
Adding~\eqref{seq:E_Delta^+} and~\eqref{seq:E_Delta^-} with the relation Eq.~\eqref{seq:get_v} yields
\begin{equation}
    \mathbb{E}[\mathrm{d}\bm{x}|\bm{X}_m=\bm{x}]=\bm{v}(\bm{x},t_m)\,\mathrm{d}t+o(\mathrm{d}t).
    \label{seq:cal_dx_xm}
\end{equation}

For the covariance, conditional independence (\hyperlink{lem:S1}{Lemma S1}) gives
\begin{equation}
    \mathrm{Cov}(\mathrm{d}\bm{x}\,|\,\bm{X}_m=\bm{x})=
    \mathrm{Cov}(\bm\Delta^+\,|\bm{X}_m=\bm{x})
    +\mathrm{Cov}(\bm\Delta^-\,|\bm{X}_m=\bm{x}).
    \label{seq:cov_sum}
\end{equation}
By the standard second-moment expansions for Itô diffusions (or Euler-Maruyama with frozen coefficients~\cite{maruyama1955continuous,kloeden1992numerical}),
\begin{equation}
    \mathrm{Cov}(\bm\Delta^+\,|\bm{X}_m=\bm{x})
    =\matbf{a}(\bm{x},t_m)\,h+o(h).
    \label{seq:cov_Delta^+}
\end{equation}
The reversed diffusion has the same diffusion matrix $\matbf{a}(\cdot,t_m)$ at $s=0$, hence likewise
\begin{equation}
    \mathrm{Cov}(\bm\Delta^-\,|\bm{X}_m=\bm{x})
    =\matbf{a}(\bm{x},t_m)\,h+o(h).
    \label{seq:cov_Delta^-}
\end{equation}
Combining~\eqref{seq:cov_sum}-\eqref{seq:cov_Delta^-} gives
\begin{equation}
    \mathrm{Cov}(\mathrm{d}\bm{x}(t)|\bm{X}_m=\bm{x})=
    \matbf{a}(\bm{x},t_m)\,\mathrm{d}t+o(\mathrm{d}t).
    \label{seq:cal_cov_dx_xm}
\end{equation}







At this stage the midpoint-conditioned increment already has the correct mean and covariance. The only remaining question is whether multiplicative-noise corrections beyond Gaussian order can affect $I(\bm\eta_t;\bm X_m)$ at order $\mathrm dt$.


\bigskip
\noindent\textbf{$\bullet$ Strong It\^{o}-Taylor expansion and normalized sum}

For short-time approximations of an It\^{o} SDE up to order $O(\mathrm{d}t)$, the Euler–Maruyama (EM) scheme is well known.
However, in a strict sense, there exist additional effects of order $O(\mathrm{d}t)$ that influence the distribution beyond the mean drift in multiplicative-noise case.
These include deformations of the local shape of the distribution and, in the presence of multidimensional noise, 
orientation or circulation effects at the pathwise level.
Although these contributions have zero mean and therefore do not appear as drift terms, 
their impact on higher-order statistics beyond the mean and leading-order covariance is of order $O(\mathrm{d}t)$~\cite{kloeden1992numerical,milstein1975strong}.
The mutual information, however, can be sensitive to these effects.
Therefore, to evaluate the mutual information accurately up to order $O(\mathrm{d}t)$, 
it is necessary to go beyond the EM scheme and consider the strong It\^{o}-Taylor expansion, which incorporates all such 
$O(\mathrm{d}t)$ contributions.

We use this framework at the midpoint, where both half-steps are expanded around the same space-time point $(\bm{x},t_m)$ and thus share the same $\matbf{B}(\bm{x},t_m)$ and its spatial derivatives (see subsection C). Because of sufficient smoothness and regularity conditions \hyperlink{assumption:A1}{A1}-\hyperlink{assumption:A4}{A4}, the It\^{o}-Taylor expansion to strong order one is valid locally. Then we can write the normalized and whitened half-steps as
\begin{align}
    \matbf{B}(\bm{x},t_m)^{-1}\frac{\bm\Delta^+}{\sqrt{h}}
        &=\bm{Z}_++\sqrt{h}\,\matbf{B}_m^{-1}\bm{F}_I(\bm{x},t_m)
        +\sqrt{h}\mathcal{T}_1(\bm{x}):\left(\bm{Z}_+\bm{Z}_+^\intercal-\mathbf{I}_d\right)
        +\sqrt{h}\mathcal{T}_2(\bm{x}):\matbf{A}_+
        +O_{L^2}(h),
        \label{seq:Delta^+_ito_taylor}
        \\
        \matbf{B}(\bm{x},t_m)^{-1}\frac{\bm\Delta^-}{\sqrt{h}}
        &=-\bm{Z}_--\sqrt{h}\,\matbf{B}_m^{-1}\bm{F}_{rev}(\bm{x},t_m)
        -\sqrt{h}\mathcal{T}_1(\bm{x}):\left(\bm{Z}_-\bm{Z}_-^\intercal-\mathbf{I}_d\right)
        -\sqrt{h}\mathcal{T}_2(\bm{x}):\matbf{A}_-
        +O_{L^2}(h),
    \label{seq:Delta^-_ito_taylor}
\end{align}
where the symbol ``$:$'' denotes tensor contraction, i.e.
$(\mathcal{T}:\matbf{M})_i\coloneq\sum_{j,k=1}^d\mathcal{T}_{ijk}\matbf{M}_{jk}$.
Here, $\mathcal{T}_1(\bm{x})$ and $\mathcal{T}_2(\bm{x})$ are deterministic tensors depending on
$\mathbf{B}(\bm{x},t_m)$ and its spatial derivatives evaluated at $(\bm{x},t_m)$ (hence they vanish in the additive-noise case).
On the other hand, $\bm{Z}_+,\bm{Z}_-\sim\mathcal{N}(0,\mathbf{I}_d)$ are normalized Gaussian random variables,
and the matrices $\matbf{A}_{\pm}$ represent the normalized  L\'{e}vy-area contribution, defined by
\begin{equation}
    (\matbf{A}_{\pm})_{ij}\coloneq
    \frac{1}{2h}\left(\matbf{J}^{\pm}_{ij}-\matbf{J}^{\pm}_{ji}\right),
    \quad
    \matbf{J}^{\pm}_{ij}\coloneq
    \int_0^h \left(\int_0^s \mathrm{d}W^{\pm,(i)}_u\right)\, \mathrm{d}W^{\pm,(j)}_s,
    \label{seq:def_levy_area_matrix}
\end{equation}
where $\bm{W}^\pm$ denote $d$-dimensional standard Wiener processes used in the auxiliary representation below,
and $d\bm{W}^\pm$ denotes their It\^o increments. Note that $\|\matbf{A}^\pm\|=O_{L^2}(1)$ by definition.
Roughly, while the first two terms on the RHS of~\eqref{seq:Delta^+_ito_taylor}--\eqref{seq:Delta^-_ito_taylor} determine the mean and leading order of covariance of the distribution (and this is exactly what the EM scheme captures), the third term $\mathcal{T}_1:(\bm{Z}\bm{Z}^\intercal-\mathrm{I}_d)$ modulates the ``shape'' of the distribution and the fourth term $\mathcal{T}_2:\matbf{A}$ effectively ``twists'' the individual paths.

We emphasize two key points: First, by \hyperlink{lem:S1}{Lemma S1}, $\bm{\Delta}^+$ and $\bm{\Delta}^-$ are independent conditional on $\bm{X}_m=\bm{x}$.
Therefore, we can represent the two half-step expansions using conditionally independent auxiliary random variables $(\bm{Z}_+,\matbf{A}_+)$ and $(\bm{Z}_-,\matbf{A}_-)$, which are conditionally independent given $\bm{X}_m=\bm{x}$, such that~\eqref{seq:Delta^+_ito_taylor}--\eqref{seq:Delta^-_ito_taylor} hold.
Second, the signs in~\eqref{seq:Delta^-_ito_taylor} flip because $\bm\Delta^-=\bm{x}-\bm{X}_{t_m-h}$ is the negative of a forward increment of the reversed diffusion, while the diffusion matrix (hence the coefficients of the third and fourth terms) remain unchanged.

Now, one can rewrite the normalized whitened-increment $\bm\eta_t$ in \eqref{seq:def_Binv_dx} as a normalized sum at the midpoint,
\begin{equation}
    \bm\eta_t\coloneq
    \frac{\matbf{B}_m^{-1}\mathrm{d}\bm{x}}{\sqrt{\mathrm{d}t}}
    =\frac{\matbf{B}_m^{-1}(\bm\Delta^++\bm\Delta^-)}{\sqrt{2h}}
    =\frac{1}{\sqrt{2}}\left(\matbf{B}_m^{-1}\frac{\bm\Delta^+}{\sqrt{h}}
    +\matbf{B}_m^{-1}\frac{\bm\Delta^-}{\sqrt{h}}\right),
    \label{seq:def_midpoint_normalized_sum}
\end{equation}
and adding~\eqref{seq:Delta^+_ito_taylor}-\eqref{seq:Delta^-_ito_taylor} yields
\begin{equation}
    \bm\eta_t
    =\frac{\bm{Z}_+-\bm{Z}_-}{\sqrt{2}}
    +\sqrt{\mathrm{d}t}\,\matbf{B}_m^{-1}\bm{v}(\bm{x},t_m)
    +\sqrt{\mathrm{d}t}\,\mathcal{T}_1(\bm{x})\!:\!
    \frac{\bm{Z}_+\bm{Z}_+^\intercal-\bm{Z}_-\bm{Z}_-^\intercal}{2}
    +\sqrt{\mathrm{d}t}\,\mathcal{T}_2(\bm{x})\!:\!\frac{
    \matbf{A}_+-\matbf{A}_-}{2}
    +O_{L^2}(\mathrm{d}t).
    \label{seq:eta_ito_taylor}
\end{equation}
Here, the drift term $\matbf{B}_m^{-1}\bm{v}(\bm{x},t_m)$ comes from~\eqref{seq:get_v}. Note that \eqref{seq:eta_ito_taylor} is a strict extension of Eq.~(3) in the main text for the multiplicative-noise case.
This equation isolates the entire multiplicative-noise difficulty in two potentially dangerous $O(\sqrt{\mathrm dt})$ terms. We will show that such terms are harmless at the order relevant for mutual information in the next section.

The $O_{L^2}$ notation in~\eqref{seq:Delta^+_ito_taylor}--\eqref{seq:Delta^-_ito_taylor},~\eqref{seq:eta_ito_taylor} means there exist $C>0$, $r\in\mathbb N$ for all $\mathrm dt<\mathrm dt_0$ (or $h<h_0$) such that
\begin{equation}
    \|\bm R_{\bm x}\|_{L^2}\leq
    C\big(1+\|\bm x\|^r\big)\,\mathrm dt
    \qquad
    \forall\bm x\in \mathbb R^d,
\end{equation}
and this is ensured by assumption \hyperlink{assumption:A1}{A1}--\hyperlink{assumption:A4}{A4}. Especially, the polynomial growth bounds assumption \hyperlink{assumption:A4}{A4} gives the polynomial term $(1+\|\bm x\|^r)$.

\vspace*{-0.6\baselineskip}
From this point on the proof is bookkeeping. We compare the exact midpoint-conditioned channel with its Gaussian proxy, decompose the mutual information difference and show that each resulting term is $o(\mathrm dt)$.
To this end, we first introduce an auxiliary random variable $\bm\eta_t^G$ as a surrogate for the whitened increment $\bm\eta_t$.
We define $\bm\eta_t^G$ as the output of an idealized Gaussian channel driven by the local signal $\sqrt{\mathrm dt}\,\bm s(\bm X_m,t_m)$,
\begin{equation}
    \bm\eta_t^G=\sqrt{\mathrm dt}\,\bm s(\bm X_m,t_m)+\bm N,
    \quad
    \bm N\sim\mathcal N(0,\mathbf I_d),
    \quad\bm N\perp\!\!\!\perp\bm X_m,
    \label{seq:Gaussian_channel_proxy}
\end{equation}
where $\bm s=\matbf B_m^{-1}\bm v$ represents the diffusion-metric normalized current velocity.
For brevity, hereafter we write $p_{\mathrm dt}(\bm z|\bm x)=p(\bm\eta_t=\bm z|\bm X_m=\bm x)$, $p_{\mathrm dt}(\bm z,\bm x)=p(\bm\eta_t=\bm z,\bm X_m=\bm x)$, and $p_{\mathrm dt}(\bm z)=\int p_{\mathrm dt}(\bm z,\bm x)\mathrm d\bm x$ and similarly for $q_{\mathrm dt}$. The arguments will always indicate which object is meant.

Note that the conditional density of $\bm\eta_t^G$ is exactly given by the shifted Gaussian kernel appearing in the leading order of our small-time expansion~\eqref{seq:p_dt_expansion_cancel_sqrt_dt}. Explicitly,
\begin{equation}
    q_{\mathrm dt}(\bm z|\bm x)\coloneq
    q_{\mathrm dt}\big(\bm\eta_t^G=\bm z|\bm X_m=\bm x\big) 
    = \phi\!\left(\bm z - \sqrt{\mathrm dt}\bm s(\bm x)\right) 
    = \phi\big(\bm z_c\big),
    \quad
    \bm z_c\coloneq\bm z-\sqrt{\mathrm dt}\,\bm s(\bm x),
    \label{seq:q_dt_equal_phi}
\end{equation}
where $\phi(\cdot)$ is the probability density function of the $d$-dimensional standard normal distribution. This identifies $\bm\eta_t^G$ as the ``Gaussian core'' of the dynamics, stripped of the non-Gaussian corrections and the remainder terms $\mathrm{Rem}_{\mathrm dt}$ established in~\eqref{seq:p_dt_expansion_cancel_sqrt_dt}. In the subsequent steps, $\bm\eta_t^G$ will serve as the reference for quantifying the mutual information discrepancy induced by the non-Gaussianity of the actual dynamics.

We now demonstrate that the discrepancy $\Delta I\coloneq I\big(\bm\eta_t;\bm X_m) - I\big(\bm\eta_t^G;\bm X_m)$ is of order $o(\mathrm dt)$ under assumptions \hyperlink{assumption:A1}{A1}--\hyperlink{assumption:A5}{A5} by the following steps.

\bigskip
\noindent\textbf{\textbullet\ Step 1. Decomposing upper bound of the} $|\Delta I|$

As identified in Eq.~\eqref{seq:rem_dt}, the polynomial growth of the coefficients (Assumption \hyperlink{assumption:A4}{A4}) implies that the remainder terms scale with $\|\bm X_m\|$, making a global uniform bound difficult to establish. 
To circumvent this, we consider a compact ball $B(0, R)$ of radius $R=R(\mathrm dt)$ defined in~\eqref{seq:R_dt} and centered at the origin, then decompose the discrepancy $\Delta I$ into contributions from the interior and exterior of this region. We explicitly handle this by introducing an indicator variable $S$ defined as $S=1$ if $\bm X_m \in B(0, R)$ and $S=0$ otherwise.

Applying the information chain rule $I(\bm \eta_t; \bm X_m) = I(\bm \eta_t; (\bm X_m,S)) = I(\bm \eta_t; S) + I(\bm \eta_t; \bm X_m | S)$ to both the actual dynamics and the proxy, we can decompose the magnitude of the discrepancy as:
\begin{equation}
    |\Delta I| \le 
    \big| I(\bm \eta_t; S) - I(\bm \eta_t^G; S) \big| 
    + \mathbb P(S=1)|\Delta I_1| + \mathbb P(S=0)|\Delta I_0|,
    \label{seq:deltaI_first_decom}
\end{equation}
where $\Delta I_k \coloneq I(\bm \eta_t; \bm X_m | S=k) - I(\bm \eta_t^G; \bm X_m | S=k)$ denotes the conditional information difference for each region.

The first term represents the information about the region index carried by the increments. Since $S$ is a discrete binary variable, this term is bounded by twice the Shannon entropy of $S$, i.e., $|I(\bm \eta_t; S) - I(\bm \eta_t^G; S)| \le 2H(S)$.

The core of the analysis thus reduces to the conditional terms. For each region ($S=0,1$), let $p_k$ and $q_k$ denote the conditional joint densities of the actual and proxy processes, respectively (i.e., $p_k(\cdot)=p_{\mathrm dt}(\cdot|S=k)$ and $q_k(\cdot)=q_{\mathrm dt}(\cdot|S=k)$). We utilize the following exact decomposition identity for the mutual information difference:
\begin{equation*}
    \Delta I_1 = 
    D_{\mathrm{KL}}\big(p_1(\bm z,\bm x)\|q_1(\bm z,\bm x)\big)
    - D_{\mathrm{KL}}\big(p_1(\bm z) \| q_1(\bm z)\big) 
    + \int_{B(0,R)}\!\!\!\!\mathrm d\bm x\!
    \int_{\mathbb R^d}\!\!\mathrm d\bm z\,\big(p_1(\bm z,\bm x)-q_1(\bm z, \bm x)\big)
    \ln\frac{q_1(\bm z|\bm x)}{q_1(\bm z)},
\end{equation*}
where $D_{\mathrm{KL}}(p||q)\coloneq\int p\ln(p/q)$ is the relative entropy.
Note that since $p_1(\bm z)$ and $q_1(\bm z)$ are marginals, the data processing inequality yields $D_{\mathrm{KL}}\big(p_1(\bm z)\|q_1(\bm z)\big)\leq D_{\mathrm{KL}}\big(p_1(\bm z,\bm x)\|q_1(\bm z,\bm x)\big)$. 
Also because  $p_1(\bm x)=q_1(\bm x)$, the equality $D_{\mathrm{KL}}\big(p_1(\bm z,\bm x)\|q_1(\bm z,\bm x)\big)=\mathbb E_{\bm x\in B(0,R)}\!\left[D_{\mathrm{KL}}\big(p_1(\bm z|\bm x)\|q_1(\bm z|\bm x)\big)\right]$ holds. Therefore we obtain
\begin{equation}
    |\Delta I_1| \leq 
    \underbrace{
    \mathbb E_{\bm x\in B(0,R)}\!\left[D_{\mathrm{KL}}\big(p_1(\bm z|\bm x)\|q_1(\bm z|\bm x)\big)\right] }_{A}
    + \underbrace{
    \left|\mathbb E_{\bm x\in B(0,R)}\!\!\left[
    \int_{\mathbb R^d}\!\mathrm d\bm z\,\big(p_1(\bm z|\bm x)-q_1(\bm z|\bm x)\big)
    \ln\frac{q_1(\bm z|\bm x)}{q_1(\bm z)}\right]\right|}
    _{B}.
    \label{seq:MI_decomposition_bound}
\end{equation}

Now for $|\Delta I_0|$, we divide the ``outside'' $B(0,R)^c$ into infinitely many shells by introducing $R_k\coloneq 2^k R(\mathrm dt)$. More precisely, let $A_k$ denote the shell $2^{k-1}R<\|\bm X_m\|\leq2^kR$ for $k\in\mathbb N$. Then $B(0,R)^c=\cup_{k=1}^\infty A_k$. This division is useful to obtain the upper bound of $I(\bm\eta_t;\bm X_m|S=0)$ because
\begin{equation}
\begin{aligned}
    I(\bm\eta_t;\bm X_m|S=0)
    &= h(\bm\eta_t|S=0)-\mathbb E_{\bm x|S=0}
    \left[h(\bm\eta_t|\bm X_m=\bm x,S=0)\right]
    \\
    &= h(\bm\eta_t|S=0)-
    \sum_{k=1}^\infty\frac{\mathbb P(\bm X_m\in A_k)}{\mathbb P(S=0)}\,
    \mathbb E_{\bm x\in A_k}\!
    \left[h(\bm\eta_t|\bm X_m=\bm x,S=0)\right]
    \\
    &\leq
    \underbrace{
    \frac{1}{2}\ln\left((2\pi e)^d \det\mathrm{Cov}(\bm\eta_t|S=0)\right)}
    _{G_0}
    +\frac{1}{\mathbb P(S=0)}\sum_{k=1}^\infty\,\underbrace{
    \mathbb P(\bm X_m\in A_k)\sup_{\bm x\in A_k}\ln\!\|p_0(\cdot|\bm x)\|_\infty}
    _{S_k},
    \label{seq:outside_real_I_bound}
\end{aligned}
\end{equation}
where $h(\cdot)$ is differential entropy and $\mathrm{Cov}(\bm\eta_t|S=0)$  denotes the conditional covariance matrix of $\bm\eta_t$ given $S=0$. We use the fact that Gaussian distribution maximizes the differential entropy for fixed covariance and $-h(\cdot)=\int p\ln p\leq\int p\ln\!\| p\|_\infty=\ln\!\|p\|_\infty$ for the last inequality in~\eqref{seq:outside_real_I_bound}.

Since $|\Delta I_0|\leq I(\bm\eta_t;\bm X_m|S=0)+I(\bm\eta_t^G;\bm X_m|S=0)$, we obtain
\begin{equation}
    \mathbb P(S=0)|\Delta I_0|\ \leq\ 
    \underbrace{
    \mathbb P(S=0)\!\left(I\big(\bm\eta_t^G;\bm X_m|S=0\big)+G_0\right)}
    _{K}
    +\sum_{k=1}^\infty S_k,
    \label{seq:delta_I_outside_bound}
\end{equation}
and therefore
\begin{align}
    |\Delta I|\leq
    2H(S)+A+B+K+\sum_{k=1}^\infty S_k.
    \label{seq:delta_I_upper_bound_decomposition}
\end{align}

In the remaining steps, we show that $H(S),A,B,K$ and $\sum_{k=1}^\infty S_k$ are $o(\mathrm dt)$. Here $H(S)$ controls the region label, $A$ and $B$ the interior relative-entropy and information-density errors, $K$ the exterior Gaussian contribution, and $\sum_k S_k$ the far-tail shells.

\bigskip
\noindent\textbf{\textbullet\ Step 2. Bounding the Indicator Entropy:} $H(S)=o(\mathrm dt)$

Let $P_0$ denote the tail probability $\mathbb{P}(S=0) = \mathbb{P}(\|\bm{X}_m\| > R)$. The entropy of the indicator $S$ is given by $H(S) = -P_0\ln P_0 - (1-P_0)\ln(1-P_0)$. Note that if $P_0=0$ or $P_0=1$, then $H(S)=0$, so the condition $H(S)=o(\mathrm{dt})$ holds trivially. For $P_0 \in (0,1)$, we utilize the inequality
\begin{equation}
    H(S) \leq -P_0\ln P_0 + P_0.
    \label{seq:H(S)_bound}
\end{equation}

Now, applying Markov's inequality $\mathbb P(X>c)\leq\mathbb E[X]/c$ with $R(\mathrm dt)$ defined in~\eqref{seq:R_dt} yields
\begin{subequations}\label{seq:P0_bound}
\renewcommand{\theequation}{\theparentequation-\Alph{equation}}
\begin{align}
    P_0&=\mathbb P(\|\bm X_m\|^n>R^n)
    \leq\frac{\mathbb E[\|\bm X_m\|^n]}{R^n}
    =\mathbb E[\|\bm X_m\|^n]\mathrm dt^{\kappa n}
    \quad\forall n\in\mathbb N
    \text{ under Assumption~\hyperlink{assumption:A5-A}{A5-A}},
    \label{seq:P0_bound_A}
    \\
    P_0&=\mathbb P(e^{\theta\|\bm X_m\|^{1+\alpha}}\!>e^{\theta R^{1+\alpha}})
    \leq\frac{\mathbb E[e^{\theta\|\bm X_m\|^{1+\alpha}}]}{e^{\theta R^{1+\alpha}}}
    =\mathbb E\!\left[e^{\theta\|\bm X_m\|^{1+\alpha}}\right]
    e^{-\theta(\ln(1/\mathrm dt))^{\beta(1+\alpha)}}
    \text{ under Assumption~\hyperlink{assumption:A5-B}{A5-B}}.
    \label{seq:P0_bound_B}
\end{align}
\end{subequations}
Assumption~\hyperlink{assumption:A5}{A5} ensures that each RHS of~\eqref{seq:P0_bound} remains finite.

In~\eqref{seq:P0_bound_A}, for any target order $k\in\mathbb N$, we can choose a sufficiently large $n$ such that $\kappa n > k$, which implies $P_0=o(\mathrm dt^k)$. 
Similarly, in~\eqref{seq:P0_bound_B}, since $\beta(1+\alpha)>1$ implies that the exponential factor dominates any polynomial power $\mathrm dt^k=e^{-k|\ln\mathrm dt|}$, we also have $P_0=o(\mathrm dt^k)$ for any $k\in\mathbb N$.
Therefore, we obtain the uniform bound
\begin{equation}
    P_0=\mathbb P(\|\bm X_m\|>R)=o(\mathrm dt^k)
    \quad\forall k\in\mathbb N,
    \label{seq:P0_bound_uniform}
\end{equation}
which is valid for both~\hyperlink{assumption:A5-A}{A5-A} and~\hyperlink{assumption A5-B}{A5-B}.

Using~\eqref{seq:P0_bound_uniform} with $k=2$, we write $P_0=\mathrm dt^2\epsilon(\mathrm dt)$, where $\epsilon(\mathrm dt)\rightarrow0$ as $\mathrm dt\rightarrow 0$.
This yields $P_0\ln P_0=o(\mathrm dt)$ since
\begin{equation}
\begin{aligned}
    \lim_{\mathrm dt\rightarrow 0}
    \frac{P_0\ln P_0}{\mathrm dt}
    &=\lim_{\mathrm dt\rightarrow 0}
    \mathrm dt\,\epsilon(\mathrm dt)
    \left[2\ln\mathrm dt+\ln\epsilon(\mathrm dt)\right]
    \\
    &=\lim_{\mathrm dt\rightarrow 0}
    2\epsilon(\mathrm dt)\big(\mathrm dt\ln\mathrm dt)
    +\lim_{\mathrm dt\rightarrow 0}
    \big(\epsilon(\mathrm dt)\ln\epsilon(\mathrm dt)\big)\mathrm dt
    \\
    &=0+0=0.
    \label{seq:P0lnP0_odt}
\end{aligned}
\end{equation}

Consequently, we verify that
\begin{equation}
    H(S)\leq -P_0\ln P_0+P_0=o(\mathrm dt).
    \label{seq:H(S)_odt}
\end{equation}

\bigskip
\noindent\textbf{\textbullet\ Step 3. Bounding the Interior Relative Entropy:} $A=o(\mathrm dt)$

To establish $A\coloneq\mathbb E_{\bm x\in B(0,R)}\!\left[D_{\mathrm{KL}}\big(p_1(\bm z|\bm x)\|q_1(\bm z|\bm x)\big)\right]=o(\mathrm dt)$, it suffices to show that $D_{\mathrm{KL}}\big(p_1(\bm z|\bm x)\|q_1(\bm z|\bm x)\big)=o(\mathrm dt)$ holds uniformly for $\bm x\in B(0,R)$. Within the region $\|\bm X_m\|\in B(0,R)$, we have $p_1=p_{\mathrm dt}$ and $q_1=q_{\mathrm dt}$; hence, we may directly invoke the expansion~\eqref{seq:p_dt_expansion_cancel_sqrt_dt} and the bound~\eqref{seq:rem_dt_Rdt_choosen}. However, a direct application of the Chi-square approximation is technically subtle since the tail behavior of $\mathrm{Rem}_{\mathrm dt}$ relative to the Gaussian $q_1$ does not strictly guarantee the integrability of the ratio $p_1/q_1$. Therefore, we explicitly compute $D_{KL}(p_1\|q_1)$ by decomposing the domain to demonstrate the $o(\mathrm dt)$ bound.

To this end, we introduce a cutoff radius $L(\mathrm dt)\coloneq \sqrt{(5/2)\ln(1/\mathrm dt)}$ for the centered increment variable $\bm z_c$, distinct from the spatial truncation $B(0,R)$ for $\bm X_m$. Thus, there are two cutoffs in the proof: $R(\mathrm dt)$ truncates the position variable $\bm x$, whereas $L(\mathrm dt)$ truncates the centered increment $\bm z_c$. 
We further assume that $\epsilon$ in~\eqref{seq:R_dt} is chosen sufficiently small ($<0.1$). For notational brevity, let $B_R$ and $B_L$ denote $B(0,R)$ and $B(0,L)$, respectively. The KL divergence can then be decomposed as:
\begin{equation}
\begin{aligned}
    D_{\mathrm{KL}}\big(p_1(\bm z|\bm x)\|q_1(\bm z|\bm x)\big)
    &=\int_{\mathbb R^d}p_1(\bm z|\bm x)\ln\frac{p_1(\bm z|\bm x)}{q_1(\bm z|\bm x)}\mathrm d\bm z
    =\int_{\mathbb R^d}p_1(\bm z|\bm x)\ln\Bigg(1+
    \underbrace{
    c_{\mathrm dt}(\bm z_c)\,\mathrm dt+\frac{\mathrm{Rem}_{\mathrm dt}(\bm z_c)}{q_1(\bm z|\bm x)}
    }_{u(\bm z_c;\bm x)}
    \Bigg)\mathrm d\bm z_c
    \\
    &=
    \underbrace{
    \int_{B_L}\!\!p_1(\bm z|\bm x)\ln(1+u)\mathrm d\bm z_c
    }_{A_L}
    +
    \underbrace{
    \int_{(B_L)^c}\!\!p_1(\bm z|\bm x)\ln(1+u)\mathrm d\bm z_c
    }_{A_{L^c}}.
    \label{seq:A_D_KL_integral}
\end{aligned}
\end{equation}
In the first line, the change of variables $\bm z\mapsto\bm z_c=\bm z-\sqrt{\mathrm dt}\,\bm s(\bm x)$ was employed.

We first examine the term $A_L\coloneq\int_{B_L}q_1(\bm z|\bm x)(1+u)\ln(1+u)\mathrm d\bm z_c$. In the region $\bm z_c\in B_L$, since $c_{\mathrm dt}(\cdot;\bm x)$ is a polynomial in $\bm z_c$ 
with coefficients uniformly bounded for $\bm x\in B_R$, it follows that $|c_{\mathrm dt}\,\mathrm dt|\rightarrow0$ as $\mathrm dt\rightarrow0$ uniformly for $(\bm z_c,\bm x)\in B_L\times B_R$. Furthermore, using the bound~\eqref{seq:rem_dt_Rdt_choosen} and the definition $\phi(\bm z_c)=(2\pi)^{-d/2}e^{-\|\bm z_c\|^2/2}$, we obtain
\begin{equation}
\begin{aligned}
    \sup_{(\bm z_c,\bm x)\in B_L\times B_R}
    \left|\frac{\mathrm{Rem}_{\mathrm dt}(\bm z_c,\bm x;R)}{\phi(\bm z_c)}\right|
    &\leq
    \sup_{(\bm z_c,\bm x)\in B_L\times B_R}
    C\,\mathrm dt^{\frac{3}{2}-\epsilon}(1+\|\bm z_c\|^m)
    \exp\!\left(\!\left(\frac{1}{2}-\gamma\right)\|\bm z_c\|^2\right)
    \\
    &\leq
    C\,\mathrm dt^{\frac{3}{2}-\epsilon}\,
    \text{polylog}(1/\mathrm dt)
    \exp\!\left(-\frac{5}{2}\left(\frac{1}{2}-\gamma\right)\!\!_+ \ln\mathrm dt\right)
    \\
    &\leq C\,\mathrm dt^{\frac{1}{4}-\epsilon}\,
    \text{polylog}(1/\mathrm dt)
    \rightarrow0
    \text{ as }\mathrm dt\rightarrow 0.
\end{aligned}
\label{seq:rem_over_q_bound_compact_RL}
\end{equation}
This implies that $u(\bm z_c)\rightarrow0$ uniformly in $A_L$ as $\mathrm dt\rightarrow0$. For notational clarity and to distinguish the conditional density from joint or marginal forms, we hereafter denote $q_1(\bm z|\bm x)$ as $q_{1|\bm x}$. By applying the Taylor expansion of $\ln(1+u)$ with respect to $u$, we obtain the following bound for sufficiently small $\mathrm dt$:
\begin{equation}
    |A_L|
    =
    \left|\int_{B_L}q_{1|\bm x}(1+u)\ln(1+u)\mathrm d\bm z_c\right|
    \leq
    \left|\int_{B_L}q_{1|\bm x}u\,\mathrm d\bm z_c\right|
    +O\!\left(
    \int_{B_L}q_{1|\bm x}u^2\mathrm d\bm z_c\right)
    \label{seq:A_L_expansion}.
\end{equation}

Since the probability densities integrate to unity, $\int_{\mathbb R^d} p_1(\cdot|\bm x)=\int_{\mathbb R^d} q_1(\cdot|\bm x)=1$, and noting that $p_1(\cdot|\bm x)=q_{1|\bm x}+q_{1|\bm x}u$, we have the identity $\int_{\mathbb R^d} q_{1|\bm x}u=0$. Consequently, the first term on the RHS of~\eqref{seq:A_L_expansion} can be rewritten as an integral over the complement set:
\begin{equation}
    \left|\int_{B_L}q_{1|\bm x}u\,\mathrm d\bm z_c\right|
    =\left|\int_{(B_L)^c}q_{1|\bm x}u\,\mathrm d\bm z_c\right|
    \leq\mathrm dt\int_{(B_L)^c}q_{1|\bm x}|c_{\mathrm dt}|\mathrm d\bm z_c
    +\int_{(B_L)^c}|\mathrm{Rem}_{\mathrm dt}|\mathrm d\bm z_c.
    \label{seq:q1_u_integral_bound}
\end{equation}

For the first term of~\eqref{seq:q1_u_integral_bound}, since $c_{\mathrm dt}$ is a polynomial in $\bm z_c$ with bounded coefficients (for $\bm x\in B_R$), the Gaussian tail $\exp(-\|\bm z_c\|^2/2)$ of $q_1(\bm z|\bm x)=\phi(\bm z_c)$ in the region $\bm z_c\in (B_L)^c$ (i.e., $\|\bm z_c\|>\sqrt{2.5\ln(1/\mathrm dt)}$) ensures that the integral is of order $O(\mathrm dt^{1+(5/4)})=o(\mathrm dt)$. Similarly, for the second term, incorporating the factor $\mathrm dt^{3/2-\epsilon}$ from~\eqref{seq:rem_dt_Rdt_choosen} and the Gaussian tail decay $\exp(-\gamma\|\bm z_c\|^2)$ of $\mathrm{Rem}_{\mathrm dt}$, we find it is of order $o(\mathrm dt^{3/2-\epsilon})=o(\mathrm dt)$ (given our choice of $\epsilon<0.1$). Thus, the first term of~\eqref{seq:A_L_expansion} is $o(\mathrm dt)$.

Next, we analyze the second term of~\eqref{seq:A_L_expansion}. Using~\eqref{seq:rem_dt_Rdt_choosen} and the inequality $(a+b)^2\leq2a^2+2b^2$, we have
\begin{equation*}
    \int_{B_L}q_{1|\bm x}\,u^2\mathrm d\bm z_c
    \leq2\mathrm dt^2\!\int_{B_L}q_{1|\bm x}\,c_{\mathrm dt}^2\,\mathrm d\bm z_c
    +2\int_{B_L}\frac{\mathrm{Rem}_{\mathrm dt}^2}{q_{1|\bm x}}\,\mathrm d\bm z_c.
\end{equation*}

The first integral on the RHS is $O(\mathrm dt^2)=o(\mathrm dt)$, as moments of polynomials under a Gaussian measure are finite. For the second integral, proceeding analogously to~\eqref{seq:rem_over_q_bound_compact_RL} by utilizing the bound $\|\bm z_c\|\leq L(\mathrm dt)$, we estimate its order as $o(\mathrm dt^{3-2\epsilon-5/4})$, which is $o(\mathrm dt)$. Thus, all terms on the RHS of~\eqref{seq:A_L_expansion} vanish faster than $\mathrm dt$, leading to the conclusion $A_L=o(\mathrm dt)$.

Next, we consider the contribution from the outer region, $A_{L^c}\coloneq\int_{(B_L)^c}p_1(\cdot|\bm x)\ln(p_1(\cdot|\bm x)/q_1(\cdot|\bm x))$. Recalling that $\ln p \leq p$ for all $p > 0$, we have $p_1(\cdot|\bm x)\ln p_1(\cdot|\bm x)\leq p_1(\cdot|\bm x)^2$. Furthermore, given that $-\ln q_{1|\bm x}=\text{const}+\|\bm z_c\|^2/2$, we can combine these with the expansion~\eqref{seq:p_dt_expansion_cancel_sqrt_dt} to obtain
\begin{equation}
\begin{aligned}
    A_{L^c}&\leq
    \int_{(B_L)^c}p_1(\bm z|\bm x)^2\,\mathrm d\bm z_c
    +\int_{(B_L)^c}p_1(\bm z|\bm x)\left(
    C+\frac{\|\bm z_c\|^2}{2}\right)\mathrm d\bm z_c
    \\
    &\leq
    \begin{aligned}
    &2\underbrace{
    \int_{\|\bm z_c\|>L}q_{1|\bm x}^2(1+c_{\mathrm dt}\,\mathrm dt)^2\mathrm d\bm z_c
    }_{T_1}
    +2\underbrace{
    \int_{\|\bm z_c\|>L}\mathrm{Rem}_{\mathrm dt}^2\mathrm d\bm z_c
    }_{T_2}
    \\
    &\qquad\qquad\qquad\qquad\quad
    +C\underbrace{
    \int_{\|\bm z_c\|>L}q_{1|\bm x}(1+|c_{\mathrm dt}|\mathrm dt)
    (1+\|\bm z_c\|^2)\mathrm d\bm z_c
    }_{T_3}
    +C\underbrace{
    \int_{\|\bm z_c\|>L}|\mathrm{Rem}_{\mathrm dt}|
    (1+\|\bm z_c\|^2)\,\mathrm d\bm z_c
    }_{T_4},
    \end{aligned}
\end{aligned}
    \label{seq:A_Lc_bound}
\end{equation}
where the inequality $(a+b)^2\leq2a^2+2b^2$ is used for the first two terms.

Analyzing $T_1$, since $c_{\mathrm dt}(\bm z_c)$ is a polynomial in $\bm z_c$, the integrand takes the form $\text{poly}(\bm z_c)\exp(-\|\bm z_c\|^2)$. Integrating over the region $\|\bm z_c\|>L$, the integral scales as $\text{poly}(L)\exp(-L^2)$, which is $O(\text{polylog}(1/\mathrm dt)\,\mathrm dt^{5/2})=o(\mathrm dt)$. Similarly, $T_3$ is characterized by the form $\text{poly}(L)\exp(-L^2/2)$, yielding $O(\text{polylog}(1/\mathrm dt)\,\mathrm dt^{5/4})=o(\mathrm dt)$.

For the remainder terms, we utilize~\eqref{seq:rem_dt_Rdt_choosen}, which gives $\mathrm{Rem}_{\mathrm dt}^2\leq C \mathrm dt^{3-2\epsilon}\text{poly}(\bm z_c)\exp(-2\gamma\|\bm z_c\|^2)$. Integrating this bound leads to $T_2\leq O(\text{polylog}(1/\mathrm dt)\,\mathrm dt^{3-2\epsilon+5\gamma})=o(\mathrm dt)$. By a similar logic, we obtain $T_4\leq O(\text{polylog}(1/\mathrm dt)\,\mathrm dt^{3/2-\epsilon+5\gamma/2})=o(\mathrm dt)$ (recalling our choice of $\epsilon < 0.1$). As all terms on the RHS of~\eqref{seq:A_Lc_bound} are $o(\mathrm dt)$, it follows that $A_{L^c}=o(\mathrm dt)$. Consequently, we arrive at the final conclusion for Step 3,
\begin{equation}
    A=\mathbb E_{\bm x\in B(0,R)}[A_L+A_{L^c}]
    =\mathbb E_{\bm x\in B(0,R)}[o(\mathrm dt)]
    =o(\mathrm dt).
    \label{seq:A_odt}
\end{equation}

\noindent\textbf{\textbullet\ Step 4. Bounding the Interior Information Density Difference:} $B=o(\mathrm dt)$

Now, let us examine the term $B\coloneq|\mathbb E_{\bm x\in B_R}[\int (p_{1|\bm x}(\bm z)-q_{1|\bm x}(\bm z))\ln(q_{1|\bm x}(\bm z)/q_1(\bm z))\,\mathrm d\bm z]|$. We begin by analyzing the information density, which is given by logarithmic ratio $\ln(q_{1|\bm x}/q_1)$. Recalling that $q_{1|\bm x}(\bm z)=\phi(\bm z_c)=\phi(\bm z-\sqrt{\mathrm dt}\,\bm s(\bm x))$, the marginal density $q_1(\bm z)$ is given by the mixture:
\begin{equation}
    q_1(\bm z)=\phi(\bm z)\,
    \mathbb E_{\bm x\in B_R}\!\!\left[
    \exp\left(\bm z\cdot\big(\sqrt{\mathrm dt}\,\bm s\big)
    -\frac{\|\bm s\|^2\mathrm dt}{2}
    \right)\right].
    \label{seq:q_1_expression_by_q_1x}
\end{equation}

Here, $\bm s(\bm x)=\matbf B_m^{-1}\bm v(\bm x)$. The inverse diffusion matrix $\matbf B_m^{-1}$ is globally bounded due to the uniform ellipticity condition in Assumption~\hyperlink{assumption:A1}{A1}. If we assume bounded $\bm v$ via~\hyperlink{assumption:A5-A}{A5-A}, then $\bm s$ is globally bounded. Alternatively, under Assumption~\hyperlink{assumption:A5-B}{A5-B}, the relation $\bm v=(\bm F_I-\bm F_{rev})/2$ from~\eqref{seq:get_v}, combined with the structural form of $\bm F_{rev}$ in~\eqref{seq:def_F_rev} (involving linear combinations of $\bm F_I$, $\nabla\ln p$, $\matbf B_m$, and their derivatives), implies that $\bm s(\bm x)$ exhibits at most polynomial growth in $\bm x$. This follows because $\matbf B_m$ and its derivatives are globally bounded by~\hyperlink{assumption:A2}{A2}, while the drift and score satisfy polynomial growth bounds by~\hyperlink{assumption:A4}{A4}. Thus, strictly speaking, we have the global bounds
\begin{subequations}\label{seq:s_bound}
\renewcommand{\theequation}{\theparentequation-\Alph{equation}}
\begin{align}
    \|\bm s(\bm x)\|&\leq C_{s,A}
    \text{ under Assumption~\hyperlink{assumption:A5-A}{A5-A}},
    \label{seq:s_bound_A}
    \\
    \|\bm s(\bm x)\|&\leq C_{s,B}
    (1+\|\bm x\|^m)   
    \text{ under Assumption~\hyperlink{assumption:A5-B}{A5-B}}.
    \label{seq:s_bound_B}
\end{align}
\end{subequations}

Under~\hyperlink{assumption:A5-A}{A5-A}, $\bm s(\bm x)$ is globally bounded. Under~\hyperlink{assumption:A5-B}{A5-B}, by choosing $R(\mathrm dt)$ as in~\eqref{seq:R_dt_B}, for $\bm x\in B_R$ (i.e., $\|\bm x\|\leq (\ln\mathrm (1/dt))^\beta$), the term $(1+\|\bm x\|^m)$ scales as $\text{polylog}(1/\mathrm dt)$. Consequently, regardless of the specific assumption (\hyperlink{assumption:A5-A}{A5-A} or~\hyperlink{assumption:A5-B}{A5-B}), we can uniformly bound $\|\bm s(\bm x)\|\leq C_s\,\text{polylog}(1/\mathrm dt)$ within the region $B_R$. This implies $\|\sqrt{\mathrm dt}\,\bm s(\bm x)\|\leq C_s\sqrt{\mathrm dt}\ \text{polylog}(1/\mathrm dt)$. Therefore, for any arbitrary $\epsilon>0$, there exists $C_{s,\epsilon},\mathrm dt_0(\epsilon)>0$ such that
\begin{equation}
    \|\sqrt{\mathrm dt}\,\bm s\|\leq \mathrm C_{s,\epsilon}\,dt^{1/2-\epsilon}
    \quad\forall\mathrm dt<\mathrm dt_0(\epsilon).
    \label{seq:sqrt_dt_s_bound}
\end{equation}

In the remainder of Step 4, we assume $\mathrm dt$ is sufficiently small to satisfy~\eqref{seq:sqrt_dt_s_bound}. Using the inequalities $\big|\bm z\cdot(\sqrt{\mathrm dt}\,\bm s)\big|\leq\|\bm z\|\|\sqrt{\mathrm dt}\bm s\|\leq C_{s,\epsilon}\|\bm z\|\mathrm dt^{1/2-\epsilon}$ and $\|\bm s\|^2\mathrm dt\leq C_{s,\epsilon}^2\,\mathrm dt^{1-2\epsilon}$, we can derive upper and lower bounds for the expectation term in~\eqref{seq:q_1_expression_by_q_1x}:
\begin{equation}
    \phi(\bm z)\exp\big(\!-C_{s,\epsilon}\|\bm z\|dt^{1/2-\epsilon}
    -C_{s,\epsilon}^2\,dt^{1-2\epsilon}/2\big)
    \leq q_1(\bm z)
    \leq
    \phi(\bm z)\exp\big(C_{s,\epsilon}\|\bm z\|dt^{1/2-\epsilon}\big),
    \label{seq:p1_sandwitch_bound}
\end{equation}
which leads to the following bound on the log-ratio $\ln(q_1(\bm z)/\phi(\bm z))$,
\begin{equation}
    \left|\ln\frac{q_1(\bm z)}{\phi(\bm z)}\right|
    \leq
    C_{s,\epsilon}\|\bm z\|dt^{1/2-\epsilon}+
    \frac{C_{s,\epsilon}^2}{2}dt^{1-2\epsilon}.
    \label{seq:p1_z_bound}
\end{equation}

Similarly, applying the same logic to $\phi(\bm z_c)=\phi(\bm z)\exp\!\big(\bm z\cdot\bm s\sqrt{\mathrm dt}-\|\bm s\|^2\mathrm dt/2\big)$ yields an analogous bound
\begin{equation}
    \left|\ln\frac{\phi(\bm z_c)}{\phi(\bm z)}\right|
    \leq
    C_{s,\epsilon}\|\bm z\|dt^{1/2-\epsilon}+
    \frac{C_{s,\epsilon}^2}{2}dt^{1-2\epsilon}.
    \label{seq:phi_z_c_bound}
\end{equation}

Combining~\eqref{seq:p1_z_bound} and~\eqref{seq:phi_z_c_bound}, we obtain
\begin{equation}
    \left|\ln\frac{q_1(\bm z|\bm x)}{q_1(\bm z)}\right|
    \leq
    \left|\ln\frac{\phi(\bm z_c)}{\phi(\bm z)}\right|
    +\left|\ln\frac{q_1(\bm z)}{\phi(\bm z)}\right|
    \leq
    2C_{s,\epsilon}\|\bm z\|\mathrm dt^{\frac{1}{2}-\epsilon}
    +C_{s,\epsilon}^2\mathrm dt^{1-2\epsilon}
    \leq2C_{s,\epsilon}\|\bm z_c\|\mathrm dt^{\frac{1}{2}-\epsilon}
    +3C_{s,\epsilon}^2\mathrm dt^{1-2\epsilon},
    \label{seq:ln_q1x_q1_bound}
\end{equation}
where the last inequality utilizes $\bm z = \bm z_c + \sqrt{\mathrm dt}\,\bm s$ and the bound~\eqref{seq:sqrt_dt_s_bound}. 

Finally, combining this estimate with the density expansion~\eqref{seq:p_dt_expansion_cancel_sqrt_dt} and the remainder bound~\eqref{seq:rem_dt_Rdt_choosen}, we obtain the bound of the integral for $B$:
\begin{equation}
    \begin{aligned}
    \int|p_1(\bm z|\bm x)-q_1(\bm z|\bm x)|
    \left|\ln\frac{q_1(\bm z|\bm x)}{q_1(\bm z)}\right|
    \mathrm d\bm z_c
    \leq
    \int\left(\mathrm dt\,|c_{\mathrm dt}|\,\phi(\bm z_c)
    +C\,\mathrm dt^{\frac{3}{2}-\epsilon}(1+\|\bm z_c\|^m)e^{-\gamma\|\bm z_c\|^2}\right)
    \left|\ln\frac{q_1(\bm z|\bm x)}{q_1(\bm z)}\right|
    \\
    \leq
    \begin{aligned}
        &\quad C_1\,\mathrm dt^{\frac{3}{2}-\epsilon}
        \underbrace{
        \int |c_{\mathrm dt}|\|\bm z_c\|\phi(\bm z_c)\mathrm d\bm z_c}_{B_1}
        +
        C_2\,\mathrm dt^{2-2\epsilon}
        \underbrace{
        \int |c_{\mathrm dt}|\,\phi(\bm z_c)\mathrm d\bm z_c}_{B_2}
        \\
        &\qquad 
        +C_3\,\mathrm dt^{2-2\epsilon}\underbrace{
        \int(1+\|\bm z_c\|^{m+1})e^{-\gamma\|\bm z_c\|^2}\mathrm d\bm z_c}_{B_3}
        +C_4\,\mathrm dt^{\frac{5}{2}-3\epsilon}
        \underbrace{\int(1+\|\bm z_c\|^m)e^{-\gamma\|\bm z_c\|^2}\mathrm d\bm z_c}_{B_4}.
    \end{aligned}
    \end{aligned}
    \label{seq:b_bound}
\end{equation}
Since $c_{\mathrm dt}$ is a polynomial in $\bm z_c$ with coefficients bounded for $\bm x\in B_R$, the integrals $B_1$ and $B_2$ are finite due to the finiteness of Gaussian moments. Similarly, $B_3$ and $B_4$ are finite as they involve integrals of polynomials against Gaussian tails $\exp(-\gamma\|\bm z_c\|^2)$. Consequently, the RHS of~\eqref{seq:b_bound} is dominated by the leading order term $O(\mathrm dt^{3/2-\epsilon})$, which is $o(\mathrm dt)$ when taking small $\epsilon$. This yields the conclusion for $B$,
\begin{equation}
    B=\big|\mathbb E_{\bm x\in B_R}[o(\mathrm dt)]\big|=o(\mathrm dt).
    \label{seq:B_odt}
\end{equation}

\noindent\textbf{\textbullet\ Step 5. Bounding the Exterior Information:} $K=o(\mathrm dt)$

We now turn our attention to the term $K\coloneq \mathbb P(S=0)\big[I(\bm\eta_t^G;\bm X_m|S=0)+\frac{1}{2}\ln\!\big((2\pi e)^d\det\mathrm{Cov}(\bm\eta_t|S=0)\big)\big]$, where $\mathrm{Cov}(\bm\eta_t|S=0)$ denotes the conditional covariance matrix of $\bm\eta_t$ given $S=0$. Conditioned on $S=0$, $\bm\eta_t^G$ represents the output of a Gaussian channel with input $\sqrt{\mathrm dt}\,\bm s(\bm X_m)|S=0$ (as defined in~\eqref{seq:Gaussian_channel_proxy}). Therefore, invoking the standard capacity bound for Gaussian channels yields:
\begin{equation}
    I(\bm\eta_t^G;\bm X_m|S=0)
    \leq
    \frac{1}{2}\ln\det\!\big(\mathbf I_d
    +\mathrm dt\,\mathrm{Cov}(\bm s(\bm X_m)|S=0)\big)
    \leq
    \frac{\mathrm dt}{2}\mathbb E\!\left[
    \|\bm s(\bm X_m)\|^2|S=0\right].
    \label{seq:I_gauss_out_bound}
\end{equation}
Here, the final inequality follows from the relation $\ln\det(\mathbf I_d+\matbf A)\leq\mathrm{Tr}(\matbf A)$ for any positive semi-definite matrix $\matbf A$.

Multiplying both sides of~\eqref{seq:I_gauss_out_bound} by $\mathbb P(S=0)$, we obtain
\begin{equation}
    \mathbb P(S=0)I(\bm\eta_t^G;\bm X_m|S=0)
    \leq
    \frac{\mathrm dt}{2}\mathbb P(S=0)\mathbb E[\|\bm s(\bm X_m)\|^2|S=0]
    =\frac{\mathrm dt}{2}\mathbb E[\|\bm s(\bm X_m)\|^2\bm 1_{S=0}],
    \label{seq:P(S=0)I_G_bound}
\end{equation}
where $\bm 1_{S=0}$ denotes the indicator function. Applying the Cauchy-Schwarz inequality to the RHS of~\eqref{seq:P(S=0)I_G_bound} gives
\begin{equation}
    \mathbb E[\|\bm s\|^2\bm 1_{S=0}]\leq\mathbb E[\|\bm s\|^4]^{\frac{1}{2}}\mathbb E[\bm 1_{S=0}]^{\frac{1}{2}}
    =\mathbb E[\|\bm s\|^4]^{\frac{1}{2}}\mathbb P(S=0)^{\frac{1}{2}}.
    \label{seq:E_s^2_1_CS_bound}
\end{equation}

As discussed in Step 4, $\bm s(\bm x)$ exhibits at most polynomial growth in $\bm x$; combined with the moment assumption~\hyperlink{assumption:A5}{A5}, this ensures $\mathbb E[\|\bm s\|^4]<\infty$. Recalling from~\eqref{seq:P0_bound_uniform} that $\mathbb P(S=0)^{1/2}=o(\mathrm dt)$, the estimates~\eqref{seq:P(S=0)I_G_bound}--\eqref{seq:E_s^2_1_CS_bound} imply $\mathbb P(S=0)I(\bm\eta_t^G;\bm X_m|S=0)=o(\mathrm dt)$.

Next, to bound $G_0\coloneq\frac{1}{2}\ln\!\big((2\pi e)^d\det\mathrm{Cov}(\bm\eta_t|S=0)\big)$, we invoke the inequality $\det\matbf A\leq(\mathrm{Tr}\matbf A/d)^d$ for positive semi-definite matrices. This yields:
\begin{equation}
    G_0\leq
    C+\frac{d}{2}\ln\mathrm{Tr}[\mathrm{Cov}(\bm\eta_t|S=0)]
    \leq
    C+\frac{d}{2}\ln\mathbb E[\|\bm\eta_t\|^2|S=0]
    \leq
    C+\frac{d}{2}\ln\frac{\mathbb E[\|\bm\eta_t\|^2\bm1_{S=0}]}{\mathbb P(S=0)}
    \leq
    C_1+C_2\ln\frac{1}{\mathbb P(S=0)}.
    \label{seq:G_0_bound}
\end{equation}

The last inequality utilizes $\mathbb E[\|\bm\eta_t\|^2\bm1_{S=0}]\leq\mathbb E[\|\bm\eta_t\|^2]$ and the finiteness of the second moment $\mathbb E[\|\bm\eta_t\|^2]<\infty$, which follows from the Itô-Taylor expansion~\eqref{seq:eta_ito_taylor}. Multiplying~\eqref{seq:G_0_bound} by $\mathbb P(S=0)$ and applying the decay rates established in~\eqref{seq:P0_bound_uniform} and~\eqref{seq:P0lnP0_odt}, we find $\mathbb P(S=0)G_0 \leq C_1\mathbb P(S=0)+C_2\mathbb P(S=0)\ln(1/\mathbb P(S=0))=o(\mathrm dt)$. Consequently, we arrive at the desired conclusion:
\begin{equation}
    K=\mathbb P(S=0)(I(\bm\eta_t^G;\bm X_m|S=0)+G_0)=o(\mathrm dt).
    \label{seq:K_odt}
\end{equation}

\bigskip
\noindent\textbf{\textbullet\ Step 6. Bounding the Infinite Shell sum:} $\sum_{k=1}^\infty S_k=o(\mathrm dt)$ \textbf{and Concluding} $\Delta I=o(\mathrm dt)$

To analyze the total sum $\sum_k S_k$, we first consider the individual terms defined by $S_k\coloneq\mathbb P(\bm X_m\in A_k)\times\sup_{\bm x\in A_k}\!\ln\|p_0(\cdot|\bm x)\|_\infty$. The event $\bm X_m\in A_k$ corresponds to the shell $2^{k-1}R<\|\bm X_m\|\leq 2^k R$; hence, we have the bound $\mathbb P(\bm X_m\in A_k)\leq P_k\coloneq\mathbb P(\|\bm X_m\|>2^{k-1}R)$. Applying Markov's inequality analogously to~\eqref{seq:P0_bound} in Step 2, we obtain the following upper bounds:
\begin{subequations}\label{seq:Pk_bound}
\renewcommand{\theequation}{\theparentequation-\Alph{equation}}
\begin{align}
    P_k&=\mathbb P(\|\bm X_m\|^n>2^{n(k-1)}R^n)
    \leq\frac{\mathbb E[\|\bm X_m\|^n]}{2^{n(k-1)}R^n}
    =\mathbb E[\|\bm X_m\|^n]\,2^{-n(k-1)}\mathrm R^{-n}
    \quad\forall n\in\mathbb N
    \text{ under Assumption~\hyperlink{assumption:A5-A}{A5-A}},
    \label{seq:Pk_bound_A}
    \\
    P_k&=\mathbb P(e^{\theta\|\bm X_m\|^{1+\alpha}}\!>e^{\theta (2^{k-1}R)^{1+\alpha}})
    \leq\frac{\mathbb E[e^{\theta\|\bm X_m\|^{1+\alpha}}]}{e^{\theta (2^{k-1}R)^{1+\alpha}}}
    =\mathbb E\!\left[e^{\theta\|\bm X_m\|^{1+\alpha}}\right]
    \!e^{-\theta (2^{k-1}R)^{1+\alpha}}
    \text{ under Assumption~\hyperlink{assumption:A5-B}{A5-B}}.
    \label{seq:Pk_bound_B}
\end{align}
\end{subequations}
Assumption~\hyperlink{assumption:A5}{A5} ensures that each RHS of~\eqref{seq:Pk_bound} remains finite.

Next, we examine the term $\sup_{\bm x\in A_k}\ln\|p_0(\cdot|\bm x)\|_\infty$. First, utilizing the expansion~\eqref{seq:p_dt_expansion_cancel_sqrt_dt}, for $\bm X_m\in A_k$, we can express the density as $p_0(\bm z|\bm x)=q_0(\bm z|\bm x)(1+c_{\mathrm dt}(\bm z_c;\bm x)\,\mathrm dt)+\mathrm{Rem}_{\mathrm dt}(\bm z_c;\bm x,R_k)$. Noting that $q_0(\bm z|\bm x)=\phi(\bm z_c)$, we obtain
\begin{equation}
    \sup_{\bm x\in A_k}
    \|p_0(\cdot|\bm x)\|_\infty
    \leq
    \sup_{\bm x\in A_k}
    \|\phi(\cdot)\|_\infty
    +\sup_{\bm x\in A_k}
    \|\phi(\cdot)\,c_{\mathrm dt}(\cdot;\bm x)\|_\infty\mathrm dt
    +\sup_{\bm x\in A_k}
    \|\mathrm{Rem}_{\mathrm dt}(\cdot;\bm x,R_k)\|_\infty.
    \label{seq:p0_sup_in_Ak}
\end{equation}

Here, the first term on the RHS of~\eqref{seq:p0_sup_in_Ak} is the supremum of the Gaussian density $\phi(\bm z_c)$, which is bounded by 1. The second term involves $c_{\mathrm dt}(\bm z_c;\bm x)$, which is a polynomial in $\bm z_c$ with coefficients growing at most polynomially in $\bm x$. Since this polynomial is multiplied by the Gaussian decay, the term $\sup_{\bm z_c}\|\phi(\cdot)\,c_{\mathrm dt}(\cdot;\bm x)\|_\infty$ can be bounded by $C(1+\|\bm x\|^r)$ for some finite global constant $C$. Given that $\sup_{\bm x\in A_k}\!\|\bm x\|=2^k R$, the second term is bounded by $C(1+(2^kR)^r)\mathrm dt$. Thus, \eqref{seq:p0_sup_in_Ak} can be rewritten as
\begin{equation}
    \sup_{\bm x\in A_k}
    \|p_0(\cdot|\bm x)\|_\infty
    \leq
    1
    +C\big(1+(2^kR)^r\big)\mathrm dt
    +\sup_{\bm x\in A_k}
    \|\mathrm{Rem}_{\mathrm dt}(\cdot;\bm x,R_k)\|_\infty.
    \label{seq:p0_sup_in_Ak_second}
\end{equation}

The remaining term $\sup_{A_k}\|\mathrm{Rem}_{\mathrm dt}\|_\infty$ is bounded using~\eqref{seq:rem_dt}. Using the fact that $\|\text{poly}(\bm z_c)\exp(-\gamma\|\bm z_c\|^2)\|_\infty<\infty$ for $\gamma>0$ and noting that the truncation radius applied here is $R_k=2^kR$ (note that we cannot use~\eqref{seq:rem_dt_Rdt_choosen} uniformly in $k$ since $R_k=2^kR(\mathrm dt)$ can be arbitrary large for fixed $\mathrm dt$), there exists a finite uniform constant $C_{\mathrm{Rem}}$ such that
\begin{subequations}\label{seq:rem_dt_bound_Ak}
\renewcommand{\theequation}{\theparentequation-\Alph{equation}}
\begin{align}
  \|\mathrm{Rem}_{\mathrm dt}\|_\infty&
  \leq C_{\mathrm{Rem}}\,\mathrm dt^{3/2}
  \big(1+(2^kR)^{a_1}\big)
  \quad\text{under Assumption~\hyperlink{assumption:A5-A}{A5-A}}
  \label{seq:rem_dt_A_Ak},
  \\
  \|\mathrm{Rem}_{\mathrm dt}\|_\infty
  &\leq C_{\mathrm{Rem}}
  \Big(\mathrm dt^{3/2}+\big(1+(2^kR)^{b_2}\big)\Big)
  \exp\!\Big(c_B^{(2)}\big(1+(2^kR)^{b_3}\big)\mathrm dt\Big)
  \big(1+(2^kR)^{b_4}\big)
  \quad\text{under~\hyperlink{assumption:A5-B}{A5-B}},
  \label{seq:rem_dt_B_Ak}
\end{align}
\end{subequations}
where the truncation term of the form $\exp(-(\cdot)_+^2/\mathrm dt)\leq1$ is omitted from the product for simplicity.

For convenience, we choose $\mathrm dt<1$ sufficiently small such that $R(\mathrm dt)>1$ hereafter. Combining the results above into~\eqref{seq:p0_sup_in_Ak_second}, there exist a uniform constant $C_\infty$ and exponents $r_A, r_B > 0$ such that
\begin{subequations}\label{seq:p0_sup_in_Ak_simple}
\renewcommand{\theequation}{\theparentequation-\Alph{equation}}
\begin{align}
    \sup_{\bm x\in A_k}
    \|p_0(\cdot|\bm x)\|_\infty
    &\leq
    C_\infty\,2^{r_A k}R^{r_A}
    \quad\text{under Assumption~\hyperlink{assumption:A5-A}{A5-A}}
    \label{seq:p0_sup_in_Ak_simple_A},
    \\
    \sup_{\bm x\in A_k}
    \|p_0(\cdot|\bm x)\|_\infty
    &\leq
    C_\infty\exp\!\big(2^{r_Bk}R^{r_B}\big)
    \quad\text{under Assumption~\hyperlink{assumption:A5-B}{A5-B}},
  \label{seq:p0_sup_in_Ak_simple_B}
\end{align}
\end{subequations}
where we replace $\mathrm dt$ by 1 using $\mathrm dt\leq 1$ to simplify the upper bounds.

~\eqref{seq:p0_sup_in_Ak_simple} yield the bound of each $S_k$ with uniform constant $C_A,C_B>0$,
\begin{subequations}\label{seq:Sk_bound}
\renewcommand{\theequation}{\theparentequation-\Alph{equation}}
\begin{align}
    S_k=\mathbb P(\bm X_m\in A_k)\sup_{\bm x\in A_k}\ln\|p_0(\cdot|\bm x)\|_\infty
    &\leq
    C_A\,2^{-n(k-1)}\mathrm R^{-n}
    (r_Ak\ln2+r_A\ln R)
    \quad\text{under Assumption~\hyperlink{assumption:A5-A}{A5-A}}
    \label{seq:Sk_bound_A},
    \\
    S_k=\mathbb P(\bm X_m\in A_k)\sup_{\bm x\in A_k}\ln\|p_0(\cdot|\bm x)\|_\infty
    &\leq
    C_B\,e^{-\theta (2^{k-1}R)^{1+\alpha}}
    2^{r_Bk}R^{r_B}
    \quad\text{under Assumption~\hyperlink{assumption:A5-B}{A5-B}}.
  \label{seq:Sk_bound_B}
\end{align}
\end{subequations}

We now proceed to evaluate the infinite sum of these terms for a fixed $R(\mathrm dt)$. First, in the case of~\eqref{seq:Sk_bound_A}, the exponential decay of $P_k$ with respect to $k$ completely dominates the polynomial growth of log-supnorm term $\sup_{A_k}\|\ln p_0(\cdot|\bm x)\|_\infty$.
Indeed, letting $r\coloneq2^{-n}<1$ and applying the standard geometric series formulas $\sum_{j=1}^\infty r^{j-1}=\frac{1}{1-r}$ and $\sum_{j=1}^\infty j\,r^{j-1}=\frac{1}{(1-r)^2}$,
we can simplify the upper bound of the infinite series. Substituting the choice $R(\mathrm dt)=\mathrm dt^{-\kappa}$ from~\eqref{seq:R_dt_A} yields
\begin{equation}
    \sum_{k=1}^\infty S_k
    \leq
    C_Ar_A R^{-n}\left(
    \frac{\ln R}{1-2^{-n}}
    +\frac{\ln 2}{(1-2^{-n})^2}\right)
    \leq
    4C_Ar_AR^{-n}\ln(2R)
    =4C_Ar_A\mathrm dt^{\kappa n}
    \ln\frac{2}{\mathrm dt^\kappa}
    \quad\text{under~\hyperlink{assumption:A5-A}{A5-A}}.
    \label{seq:sum_Sk_bound_A}
\end{equation}

By choosing an integer $n\in\mathbb N$ such that $\kappa n>1$ (this is always possible since all moments are finite under~\hyperlink{assumption:A5-A}{A5-A}), we ensure that $\sum_{k=1}^\infty S_k=o(\mathrm dt)$.

For the case of~\eqref{seq:Sk_bound_B}, although the log-supnorm term exhibits exponential growth with respect to $k$, this growth is dominated by the double-exponential decay of $P_k$. To demonstrate this rigorously, let $T_k$ denote the upper bound of $S_k$ given in the RHS of~\eqref{seq:Sk_bound_B}. Clearly, the inequality $\sum_k S_k\leq\sum_k T_k$ holds. To bound the sum $\sum_k T_k$, we evaluate the ratio of consecutive terms $\rho(k)\coloneq T_{k+1}/T_k$:
\begin{equation}
    \rho(k)=
    \frac{T_{k+1}}{T_k}
    =\frac{C_B\,e^{-\theta (2^{k}R)^{1+\alpha}}
    2^{r_B(k+1)}R^{r_B}}
    {C_B\,e^{-\theta (2^{k-1}R)^{1+\alpha}}
    2^{r_Bk}R^{r_B}}
    =2^{r_B}\exp\!\left(
    -\theta(2^{1+\alpha}-1)R^{1+\alpha}2^{(k-1)(1+\alpha)}
    \right).
    \label{seq:rho_k}
\end{equation}

Since $\theta, a, R > 0$, the ratio $\rho(k)$ is strictly decreasing in $k$, implying $\rho(k)\leq\rho(1)$ for all $k\ge 1$. Furthermore, observing that $\rho(1)\rightarrow0$ as $R\rightarrow\infty$ (which corresponds to $\mathrm dt\rightarrow0$), there exists a global threshold $\mathrm dt_0>0$ such that $\rho(k)\leq\rho(1)\leq1/2$ holds for all $k$ whenever $\mathrm dt<\mathrm dt_0$. Under this condition, the sum is bounded by a geometric series:
\begin{equation*}
    \sum_{k=1}^\infty T_k
    =T_1+\sum_{k=2}^\infty\left(\prod_{j=1}^{k-1} \rho(j)\right)T_1
    \leq T_1+\sum_{k=1}^\infty\rho(1)^kT_1
    \leq T_1+\sum_{k=1}^\infty\left(\frac{1}{2}\right)^k T_1
    =2T_1.
\end{equation*}

Substituting $R(\mathrm dt)=(\ln(1/\mathrm dt))^\beta$ with $\beta(1+\alpha)>1$ from~\eqref{seq:R_dt_B} into the expression for $T_1$, we obtain
\begin{equation}
    \sum_{k=1}^\infty S_k
    \leq\sum_{k=1}^\infty T_k\leq2T_1
    =2^{r_B+1}C_B\left(\ln\frac{1}{\mathrm dt}\right)^{\beta r_B}
    \exp\!\left(-\theta\left(\ln\frac{1}{\mathrm dt}\right)^{\beta(1+\alpha)}\right)
    =o(\mathrm dt)
    \quad\forall\mathrm dt<\mathrm dt_0
    \text{ under~\hyperlink{assumption:A5-B}{A5-B}},
    \label{seq:sum_Sk_bound_B}
\end{equation}
where the limit holds because the ratio $2T_1/\mathrm dt = 2T_1 \exp(\ln(1/\mathrm dt))$ vanishes as $\mathrm dt\rightarrow0$. Specifically, considering the exponent in terms of $x=\ln(1/\mathrm dt)$, we have $x+\beta r_B\ln x-\theta x^{\beta(1+\alpha)}\rightarrow-\infty$ as $x\rightarrow\infty$, provided that $\beta(1+\alpha)>1$.
Consequently, combining~\eqref{seq:sum_Sk_bound_A} and~\eqref{seq:sum_Sk_bound_B}, we establish the target conclusion for all cases,
\begin{equation}
    \sum_{k=1}^\infty S_k=o(\mathrm dt).
    \label{seq:sum_Sk_odt}
\end{equation}

Having established via~\eqref{seq:H(S)_odt},~\eqref{seq:A_odt},~\eqref{seq:B_odt}, and~\eqref{seq:K_odt}, together with the result~\eqref{seq:sum_Sk_odt} just derived. Thus every term on the RHS of the decomposition~\eqref{seq:delta_I_upper_bound_decomposition} is $o(\mathrm dt)$, we have successfully proven the main objective of this subsection:
\begin{equation}
    I(\bm\eta_t;\bm X_m)-I(\bm\eta_t^G;\bm X_m)=o(\mathrm dt)
    \quad\text{as }\mathrm dt\rightarrow0.
    \label{seq:deltaI_odt}
\end{equation}
Therefore the Gaussian proxy is asymptotically exact at order $\mathrm dt$ for mutual information.

\vspace*{-0.6\baselineskip}

We now determine the exact leading-order term of $I(\bm\eta_t;\bm X_m)$ in powers of $\mathrm dt$. Here, the previously derived estimate~\eqref{seq:deltaI_odt} plays a pivotal role. By Eq.~\eqref{seq:Gaussian_channel_proxy}, the proxy variable $\bm\eta_t^G$ can be viewed as the output of an additive Gaussian channel with a small signal-to-noise ratio (SNR) of order $\mathrm{d}t$. In this regime, the exact leading term of the mutual information can be calculated using the I-MMSE relation established by Guo et al.~\cite{guo2005mutual}.

Specifically, Guo et al. showed that for a Gaussian channel with input $\bm S$ and output $\bm Y \coloneq \sqrt{\mathrm{snr}}\bm S + \bm N$, the derivative of the mutual information with respect to $\mathrm{snr}$ equals half of the minimum mean-squared error (MMSE)~\cite{guo2005mutual}. Since $\mathrm{MMSE}(0) = \mathrm{Tr}\,\mathrm{Cov}(\bm S)$ at $\mathrm{snr}=0$, integrating this over small $\mathrm{snr}$ yields $I(\bm Y; \bm S) = \frac{\mathrm{snr}}{2}\mathrm{Tr}\,\mathrm{Cov}(\bm S) + o(\mathrm{snr})$. Applying this to our model~\eqref{seq:Gaussian_channel_proxy}, we obtain the exact leading term:
\begin{equation}
    I(\bm{\eta}_t^G;\bm{X}_m)
    =\frac{\mathrm{d}t}{2}\mathrm{Tr}\,\mathrm{Cov}\left[
    \bm{s}(\bm{X}_m,t_m)
    \right]+o(\mathrm{d}t).
    \label{seq:I_G_I_MMSE}
\end{equation}
By the bound~\eqref{seq:deltaI_odt}, the actual information $I(\bm\eta_t;\bm X_m)$ shares this identical leading term. Here, $\bm s = \matbf B_m^{-1}\bm v$. Using the continuity assumptions for $\bm F_I$ and $\matbf B$ (\hyperlink{assumption:A2}{A2}) and for the density (\hyperlink{assumption:A3}{A3}), we have $\bm v_m = \bm v(\bm X_t, t) + o(1)$ and $\matbf B_m^{-1} = \matbf B(\bm X_t, t)^{-1} + o(1)$. Furthermore, utilizing the definition of the diffusion tensor $\matbf{D} = \frac{1}{2}\matbf{B}\matbf{B}^\intercal$, we expand the covariance term as follows:

\begin{equation}
\begin{aligned}
    I(\bm\eta_t;\bm{X}_m)
    &=\frac{\mathrm dt}{2}\mathrm{Tr}\,\mathrm{Cov}\left[
    \matbf B(\bm X_t,t)^{-1}\bm v(\bm X_t,t)\right]
    +o(\mathrm dt)
    \\
    &=\frac{\mathrm dt}{2}\left(
    \frac{1}{2}\mathbb E\!\left[
    \bm v_t^\intercal\matbf D_t^{-1}\bm v_t
    \right]
    -\frac{1}{2}\left\|\mathbb E[\matbf D_t^{-1/2}\bm v_t]\right\|^2
    \right)+o(\mathrm dt)
    \\
    &=\frac{\mathrm dt}{4}\sigma_t
    -\frac{\mathrm dt}{4}\left\|\mathbb E[\matbf D_t^{-1/2}\bm v_t]\right\|^2
    +o(\mathrm dt).
\end{aligned}
    \label{seq:I_EP_relation}
\end{equation}
where $(\cdot)_t := (\cdot)(\bm X_t, t)$. The second equality uses the identity $\mathrm{Tr}\,\mathrm{Cov}(\bm w) = \mathbb E[\|\bm w\|^2] - \|\mathbb E[\bm w]\|^2$ for a random vector $\bm w$ and the relation $\|\matbf B^{-1}\bm v\|^2 = \bm v^\intercal (\matbf B \matbf B^\intercal)^{-1} \bm v = \frac{1}{2}\bm v^\intercal \matbf D^{-1} \bm v$. The final equality substitutes the definition of the entropy production rate~\eqref{seq:ep_rate}.

Dividing by $\mathrm dt$ and taking the limit $\mathrm dt \to 0$, we establish the generalized main identity for multiplicative noise, extending Eq.~(2) of the main text:
\begin{equation}
    \sigma_t
    =4\lim_{\mathrm dt\rightarrow0}
    \frac{I(\bm\eta_t;\bm X_m)}{\mathrm dt}
    +\|\mathbb E[\matbf D_t^{-1/2}\bm v_t]\|^2.
    \label{seq:main_identity_multi}
\end{equation}

If $\matbf D_t$ is spatially constant (i.e., additive noise), then $\mathbb E[\matbf D_t^{-1/2}\bm v_t] = \matbf D_t^{-1/2}\mathbb E[\bm v_t]$, and also $I(\bm\eta_t;\bm X_m)=I(\mathrm d\bm x;\bm X_m)$ since $\bm\eta_t=\matbf B_m^{-1}\mathrm d\bm x/\sqrt{\mathrm dt}$ becomes linear transformation with coordinate-independent matrix $\frac{1}{\sqrt{\mathrm dt}}\matbf B(t_m)^{-1}$. Hence Eq.~\eqref{seq:main_identity_multi} reduces exactly to the main identity in the main text, Eq.~(2).

The rest of the SM only propagates this result to projections, subsystem decompositions, and the RBC applications.

\vspace*{-0.6\baselineskip}

In this section, we numerically illustrate the multiplicative-noise identity~\eqref{seq:main_identity_multi} derived in Sec. I using a simple one-dimensional diffusion on a ring. This example is analytically transparent while retaining genuinely state-dependent noise, allowing us to compare the small-$\mathrm dt$ mutual information slope directly with the theoretical prediction. It also provides a useful contrast between midpoint and endpoint conditioning. In Sec. I.E, we showed that under midpoint conditioning the $\sqrt{\mathrm dt}$-order non-Gaussian corrections cancel, so that the conditional law is captured by a Gaussian channel up to $O(\mathrm dt)$ corrections; no analogous simplification is expected for endpoint conditioning. We therefore focus on the midpoint-conditioned quantity $I(\bm\eta_t;\bm X_m)$, and report $I(\bm\eta_t;\bm X_t)$ only as a control illustrating why the exact identity is formulated with the midpoint rather than with an endpoint. 

\vspace*{-0.6\baselineskip}

\vspace*{-0.6\baselineskip}

The caption of Fig.~2 lists the model equations and parameter values; here we record only the additional details needed for reproduction. Panels (a,b) were not generated from trajectory data, but from the closed-form steady state of linear additive-noise model
\begin{equation}
    \dot{\bm X}=\matbf A\bm X+\sqrt{2\matbf D}\bm\xi,
    \quad
    \matbf A=
    \begin{pmatrix}
        -k & s+a \\
        s-a & -k
    \end{pmatrix},
    \quad
    \matbf D=\matbf I.
    \label{seq:linear_Langevin_fig2}
\end{equation}

For each parameter set, the stationary covariance $\matbf C$ was obtained from the Lyapunov equation
\begin{equation}
    \matbf A\matbf C+\matbf C\matbf A^\intercal+2\matbf D=\matbf 0.
    \label{seq:lyapunov_equation}
\end{equation}

The black arrows show the drift $\bm F(\bm x)=\matbf A\bm x$, the yellow arrows show the local mean velocity
\begin{equation}
    \bm v(\bm x)=\bm F(\bm x)-\matbf D\nabla\ln p_{ss}(\bm x)
    =(\matbf A+\matbf D\matbf C^{-1})\bm x,
    \label{seq:cal_v_linear}
\end{equation}
and the contours show the stationary Gaussian density $p_{ss}(\bm x)\propto\exp\left(-\frac{1}{2}\bm x^\intercal\matbf C^{-1}\bm x\right)$.
The crosses mark the midpoint locations used for the conditional displacement plots in panels (c,d).

For panels (c,d), conditional displacement clouds were generated from the same linear model~\eqref{seq:linear_Langevin_fig2} using a two-half-step Euler-Maruyama update with $\Delta t=10^{-3}$. In each case, $10^5$ trajectories were initialized at the origin and propagated for $10^4$ steps, and the first $10^3$ steps were discarded as burn-in. The midpoint $\bm X_m$ was recorded after the first half-step, and the full displacement was defined by $\Delta\bm X=\bm X_{t+\Delta t}-\bm X_t$. Conditional samples were then selected by restricting $\bm X_m$ to two square windows centered at $(-0.6,0.6)$ and $(0.6,-0.6)$, with half-width $0.02$ in each coordinate. The panels show scatter plots of the resulting conditional displacements together with their one-dimensional marginals. Dashed crosshairs indicate the sample means, solid black lines indicate the origin, and the dashed circles indicate the $1.96\sigma$ scale of each conditional cloud.

For panels (e,f), the linear model~\eqref{seq:linear_Langevin_fig2} and the nonlinear model
\begin{equation*}
    \begin{aligned}
        \dot x&=-x+y+\epsilon y^3+\sqrt 2\,\xi_x, \\
        \dot y&=-y+\sqrt 2\,\xi_y,
    \end{aligned}
\end{equation*}
with $\matbf D=\mathrm{I}$, were used. The information rate was estimated from midpoint-conditioned displacements. In the additive-noise setting,
\[
    I(\Delta\bm X;\bm X_m)=\frac{\Delta t}{4}
    \mathrm{Tr}\big(\matbf D^{-1}
    \mathrm{Cov}(\bm v(\bm X_m))\big)+o(\Delta t),
    \quad
    \bm v(\bm x_m)=\frac{\mathbb E[\Delta\bm X|\bm X_m=\bm x_m]}{\Delta t}.
\]
For the main-text panels, we therefore used the regression-based estimator
\begin{equation}
    \hat I_{\mathrm{MMSE}}(\Delta t)\coloneq\frac{\Delta t}{4}
    \mathrm{Tr}\left(\matbf D^{-1}\hat{\mathrm{Cov}}(\hat{\bm v}(\bm X_m))\right),
    \label{seq:I_hat_MMSE}
\end{equation}
where $\hat{\bm v}(\bm x_m)$ was obtained by regressing $\Delta\bm X$ on $\bm X_m$. The subscript MMSE refers to the leading-order small-SNR Gaussian/I-MMSE expression underlying this estimator~\cite{guo2005mutual}. In practice, polynomial features of the midpoint coordinates were used together with sample splitting (cross-fitting) to reduce overfitting bias. For each parameter value, $\hat I_{\mathrm{MMSE}}(\Delta t)$ was evaluated over a range of $\Delta t$ and fitted both by
\begin{equation}
    \hat I(\Delta t)\approx m_{\mathrm{lin}}\Delta t+c
    \label{seq:m_lin}
\end{equation}
and by the constrained quadratic form
\begin{equation}
    \hat I(\Delta t)\approx m_{\mathrm{quad}}\Delta t+b\Delta t^2,
    \quad \hat I(0)=0.
    \label{seq:m_quad}
\end{equation}

The main text reports $m_{\mathrm{quad}}$ as the representative estimate of the $\Delta t\rightarrow0$ slope.

As an independent cross-check, we also computed direct mutual information estimates with a debiased KSG $k$-nearest-neighbor estimator for $k=10$, denoted by $\hat I_{\mathrm{KSG}}$. These KSG calculations were not used for the main-text panels, but only to verify that the regression-based estimator $\hat{I}_{\rm MMSE}$ gives consistent small-$\Delta t$ slopes. At fixed sample size, $\hat{I}_{\rm KSG}$ exhibits substantially larger fluctuations than $\hat{I}_{\rm MMSE}$, especially in the nonlinear case, while remaining consistent with the same $\sigma/4$ trend. The corresponding summary for the linear model and comparison plots for the nonlinear model are shown in Fig.~\ref{sfig:main_lin_summary}--\ref{sfig:main_nonlin_MMSE}.







For panel (e), the EP rate was evaluated analytically for the linear Ornstein-Uhlenbeck process. 
With stationary covariance $\matbf C$ and local mean velocity $\bm v$ in~\eqref{seq:lyapunov_equation} and~\eqref{seq:cal_v_linear}, the total EP rate is given by
\[
    \sigma=\langle\bm v^\intercal\matbf D^{-1}\bm v\rangle=
    \mathrm{Tr}\left[\matbf D^{-1}(\matbf A+\matbf D\matbf C^{-1})\matbf C(\matbf A+\matbf D\matbf C^{-1})^\intercal\right].
\]
Using the Lyapunov equation~\eqref{seq:lyapunov_equation}, this is equivalently written as
\begin{equation}
    \sigma=\mathrm{Tr}(\matbf D^{-1}\matbf A\matbf C\matbf A^\intercal)
    +\mathrm{Tr}(\matbf A).
    \label{seq:sigma_linear}
\end{equation}

For panel(f), the EP rate was estimated independently from the midpoint discretization of the Stratonovich expression
\[
    \sigma=\left\langle\bm F(\bm X_t)^\intercal\matbf D^{-1}\circ\dot{\bm X}_t\right\rangle,
\]
namely
\[
    \hat\sigma=\frac{1}{\Delta t}\left\langle
    \bm F\left(\frac{\bm X_t+\bm X_{t+\Delta t}}{2}\right)^\intercal
    \matbf D^{-1}\big(\bm X_{t+\Delta t}-\bm X_t\big)\right\rangle.
\]

For each value of $\epsilon$, $10^4$ trajectories of length $10^4$ steps were simulated with $\Delta t=10^{-3}$, starting from the origin, and the initial $5\times10^3$ steps were discarded as burn-in. This estimator follows from the steady-state identity
\[
    \sigma=\int\frac{\bm j_{ss}^\intercal\matbf D^{-1}\bm j_{ss}}{p_{ss}}\mathrm d\bm x
    =\int\bm F^\intercal\matbf D^{-1}\bm j_{ss}\mathrm d\bm x,
\]
where the second equality uses $\bm j_{ss}=\bm Fp_{ss}-\matbf D\nabla p_{ss}$ together with stationarity, so that the term involving $\nabla\ln p_{ss}$ integrates to zero under the adopted boundary conditions.

\vspace*{-0.6\baselineskip}

We consider the three-dimensional stationary OU model introduced for two hydrodynamically coupled particles driven through a stochastic trap center~\cite{das2025irreversibility}. We write $\bm z\coloneq (x_1,x_2,\lambda)^\intercal$ and use the convention
\begin{equation}
    \mathrm d\bm z=-\matbf F\bm z\,\mathrm dt+\sqrt{2\matbf D}\,\mathrm dW,
\end{equation}
where
\begin{equation*}
    \matbf F\!=\!\!
    \begin{pmatrix}
    1/\tau_1 & \epsilon/{\tau_2} & -1/\tau_1 \\
    \epsilon/\tau_1 & 1/{\tau_2} & -\epsilon/\tau_1 \\
    0 & 0 & 1/\tau_\lambda
    \end{pmatrix}\!\!,
    \;\; 
    \matbf D\!=\!\!
    \begin{pmatrix}
    D_0 & \epsilon D_0 & 0 \\
    \epsilon D_0 & D_0 & 0 \\
    0 & 0 & \theta D_0
    \end{pmatrix}\!.   
    \label{eq:Das_model_details}
\end{equation*}
The parameters are $\tau_1=1.5\,ms$, $\tau_2=2.1\,ms$, $\tau_\lambda=4.0\,ms$, $D_0=0.16\,\mu m^2s^{-1}$, and $\theta=0.56$. The two conditions used in Fig.~4d are $\epsilon=0.29$ and $\epsilon=0.49$. $\epsilon$ and $\theta$ are dimensionless. All logarithms are natural, so rates in this section are reported in $k_B s^{-1}$ after applying the factor four in the midpoint identity.

\vspace*{-0.6\baselineskip}

Synthetic trajectories were generated with the exact discrete transition of the stationary OU process. For observation interval $\delta t$ and stationary covariance $\matbf C$, the initial state is drawn from $\mathcal N(\bm 0,\matbf C)$, and subsequent states satisfy
\begin{equation}
    \bm z_{k+1}=\matbf M\bm z_k+\bm\eta_k,
    \quad
    \matbf M=\exp(-\matbf F\delta t),
    \quad
    \bm\eta_k\sim\mathcal N(\bm 0,\matbf C-\matbf M\matbf C\matbf M^\intercal).
    \label{seq:synthesis_trjs_equation}
\end{equation}

The Gaussian innovations are independent across steps and independent of the initial state. This construction initializes the process in stationarity and avoids time-integration bias. At each $\epsilon$, we generated 40 independent trajectories of duration $50\,s$ sampled at $\delta t=10^{-4} \,s$, giving 500001 recorded states per trajectory using~\eqref{seq:synthesis_trjs_equation}.

