        &=\underbrace{\mathcal F\big[\phi(\bm z-\sqrt{\mathrm dt}\,\bm s)\big](\bm u)}_{\eqqcolon\,\widetilde{\phi}(\bm u,\bm s)}
        +\sum_{j=1}^J\sqrt{\mathrm dt}^{\,j}
        \mathcal F\left[
        c_j\!\left(\bm z-\sqrt{\mathrm dt}\,\bm s;\bm x\right)\,
