        +\underbrace{\mathcal F\left[\mathrm{Rem}(\bm z,\bm x;J)\right](\bm u)}_{\eqqcolon\,\widetilde{\mathrm{Rem}}(\bm u,\bm x;J)}
        \\
        &=\widetilde{\phi}(\bm u,\bm s)
        +\sum_{j=1}^J\sqrt{\mathrm dt}^{\,j}
